window.TURNO_DATOS={"ramos":[{"codigo":"SALPX1203","nombre":"Salud Laboral y Primeros Auxilios","corto":"Salud Laboral","linea":"L1","color":"#0a7a4b","colorOscuro":"#1f9a63","docente":"Edward Flores","termina":"2027-01-04"},{"codigo":"ESTAP1204","nombre":"Estadística Aplicada","corto":"Estadística","linea":"L2","color":"#1d5fc4","colorOscuro":"#3b7be0","docente":"Leonardo Fuentes","termina":"2027-01-04"},{"codigo":"CEMCG0401","nombre":"Manejo de Crisis y Emergencias","corto":"Manejo de Crisis","linea":"L3","color":"#c2501b","colorOscuro":"#d9682f","docente":"Curso complementario","termina":"2026-11-30"}],"semanas":[{"id":"CEMCG0401-L1","codigo":"CEMCG0401","curso":"Manejo de Crisis y Emergencias","etiqueta":"Lección","semana":1,"titulo":"Fundamentos del manejo de crisis","desde":"2026-11-03","hasta":"2026-11-30","entregas":[],"misiones":[{"id":"conceptos","estacion":"Conceptos","titulo":"Incidente, emergencia, desastre o crisis","minutos":6,"intro":"Las cuatro palabras que el curso usa todo el tiempo y cómo diferenciarlas.","pasos":[{"t":"tarjetas","cartas":[["Incidente","Evento no deseado o fuera de lo normal, acotado y controlable con recursos y procedimientos habituales."],["Emergencia","Peligro real o inminente que exige respuesta inmediata para proteger personas, bienes, procesos o medioambiente."],["Desastre","Alteración grave cuyos impactos superan la capacidad habitual de respuesta y requieren apoyo extraordinario."],["Crisis","Situación que altera significativamente la normalidad y amenaza la estabilidad, continuidad, confianza o legitimidad de una organización."],["Escalamiento","Aumento de la gravedad, alcance o complejidad por la evolución del evento o por una respuesta insuficiente. Ej.: incidente → emergencia → crisis."],["Elementos clave de una crisis","Incertidumbre, urgencia, impacto, presión para decidir, coordinación y comunicación oportuna."]]},{"t":"clasificar","id":"c1-1","p":"¿Qué es cada situación?","cats":["Incidente","Emergencia","Desastre","Crisis"],"items":[["Un torniquete del acceso se traba; mantención lo repara en 10 minutos.",0],["Humo en una bodega de la estación; hay que evacuar el andén ya.",1],["Un terremoto daña la vía y varias ciudades; se necesita ayuda nacional.",2],["Fallas repetidas, usuarios furiosos en redes y la empresa pierde confianza pública.",3]],"exp":"Incidente: acotado y controlable. Emergencia: peligro inmediato. Desastre: supera las capacidades habituales. Crisis: amenaza la estabilidad, continuidad o confianza de la organización."},{"t":"mc","id":"c1-2","p":"Según la infografía, una crisis suele surgir por la combinación de…","ops":["Mala suerte y falta de dinero","Amenaza, vulnerabilidad y baja capacidad de respuesta","Rumores y redes sociales","Un solo error humano"],"ok":1,"exp":"Amenaza + vulnerabilidad + baja capacidad de respuesta es la idea central de la lección 1."}]},{"id":"tipos","estacion":"Tipos y causas","titulo":"De dónde nacen las crisis","minutos":5,"intro":"Tipos de crisis, factores desencadenantes y señales tempranas.","pasos":[{"t":"tarjetas","cartas":[["Tipos de crisis según su origen","Naturales, tecnológicas, sanitarias, sociales, organizacionales, reputacionales, económicas y operacionales."],["Crisis súbita","Aparece de golpe y exige decisiones inmediatas con poca información. Ej.: accidente grave."],["Crisis progresiva","Se desarrolla de a poco, con señales acumuladas o fallas reiteradas que nadie atendió."],["Factores internos","Falta de planificación, ausencia de protocolos, liderazgo débil, comunicación deficiente, falta de capacitación, mantenimiento insuficiente."],["Factores externos","Fenómenos naturales, emergencias sanitarias, cortes de servicios, fallas de proveedores, conflictos sociales, cambios regulatorios, presión pública."],["Señal temprana","Indicio previo que advierte deterioro o posible escalamiento: reclamos reiterados, fallas técnicas, rumores internos, sobrecarga."]]},{"t":"clasificar","id":"c1-3","p":"¿Factor interno o externo?","cats":["Interno","Externo"],"items":[["Ausencia de protocolos",0],["Corte de luz de la compañía eléctrica",1],["Mantenimiento insuficiente",0],["Temporal de viento y lluvia",1],["Liderazgo débil",0],["Falla de un proveedor",1]],"exp":"Internos: nacen dentro de la organización. Externos: vienen del entorno. También hay factores mixtos."},{"t":"mc","id":"c1-4","p":"Una empresa tiene cortes eléctricos breves por meses, no hace mantención, y un día una falla mayor detiene todo. ¿Qué tipo de crisis es?","ops":["Súbita, porque nadie la esperaba","Progresiva, porque hubo señales previas que no se atendieron","Natural","No es crisis, es un incidente"],"ok":1,"exp":"Es el caso aplicado del curso: la crisis no fue sorpresiva, existían señales tempranas."}]},{"id":"anden","estacion":"Caso en el andén","titulo":"¿Qué está pasando?","minutos":4,"intro":"Las preguntas para reconocer una situación crítica, aplicadas a tu estación.","pasos":[{"t":"lectura","titulo":"Situación","texto":["Viernes 18:30. Se cae el sistema de venta de pasajes y el tren de las 18:45 lleva 25 minutos de atraso. El andén se llena, algunos pasajeros discuten con el personal y alguien graba y sube un video.","Eres el guardia de turno."]},{"t":"orden","id":"c1-5","p":"Ordena las preguntas para reconocer la situación, de la más urgente a la de seguimiento.","items":["¿Existe riesgo para las personas?","¿Qué ocurrió y a quién afecta?","¿Qué información está confirmada?","¿Puede escalar?","¿Quién debe coordinar y se requiere apoyo externo?"],"exp":"Primero la seguridad de las personas, luego entender el evento, separar lo confirmado, evaluar escalamiento y definir coordinación y apoyos."},{"t":"mc","id":"c1-6","p":"En esta situación, ¿cuál es la principal señal de que puede escalar a crisis?","ops":["Que el sistema de venta tenga errores","El andén lleno, la tensión con el personal y el video en redes","El atraso de 25 minutos por sí solo","Que sea viernes"],"ok":1,"exp":"La aglomeración es un riesgo para las personas y el video expone a la empresa. Esa combinación puede afectar la seguridad y la confianza."}]}]},{"id":"CEMCG0401-L2","codigo":"CEMCG0401","curso":"Manejo de Crisis y Emergencias","etiqueta":"Lección","semana":2,"titulo":"Decisiones y comunicación en crisis","desde":"2026-11-04","hasta":"2026-11-30","entregas":[],"misiones":[{"id":"info","estacion":"Información","titulo":"Confirmado, probable o rumor","minutos":5,"intro":"El análisis situacional inicial empieza por ordenar la información.","pasos":[{"t":"tarjetas","cartas":[["Información confirmada","Verificada por una fuente confiable o evidencia suficiente. Sirve para decidir y comunicar."],["Información probable","Coherente y parcialmente respaldada, pero todavía requiere validación."],["Información no verificada","Dato, versión o rumor sin comprobar. Se monitorea, pero no se comunica como hecho."],["Análisis situacional inicial","Proceso breve para establecer qué ocurrió, a quién afecta, qué riesgos hay, qué está confirmado y qué priorizar."],["Toma de decisiones en crisis","Elegir acciones oportunas y revisables bajo presión e información incompleta. Decidir no es improvisar."]]},{"t":"clasificar","id":"c2-1","p":"Caída del sistema digital de una institución pública. Clasifica cada antecedente.","cats":["Confirmada","Probable","No verificada"],"items":[["El sistema está caído",0],["Hay usuarios reclamando",0],["La causa sería una falla eléctrica",1],["Se comenta que hubo filtración de datos",2]],"exp":"Es la actividad oficial de la lección 4: lo observado es confirmado, la causa supuesta es probable y el comentario es no verificado."}]},{"id":"sesgos","estacion":"Decidir bajo presión","titulo":"Los sesgos que engañan","minutos":5,"intro":"Factores que distorsionan las decisiones: tiempo, estrés, rumores, fatiga y sesgos.","pasos":[{"t":"tarjetas","cartas":[["Sesgo de confirmación","Buscar solo información que confirma lo que ya crees. Ej.: asumir que la falla es menor e ignorar señales de gravedad."],["Sesgo de normalidad","Creer que no será grave porque antes no lo fue. Lleva a subestimar el riesgo."],["Sesgo de autoridad","Aceptar una decisión solo porque viene de alguien con cargo, sin analizar su fundamento."],["Sesgo de disponibilidad","Decidir según experiencias recientes aunque el contexto actual sea distinto."],["Fatiga","Afecta concentración, memoria y juicio. Por eso las respuestas largas necesitan turnos, descansos y relevos."]]},{"t":"clasificar","id":"c2-2","p":"¿Qué sesgo aparece?","cats":["Confirmación","Normalidad","Autoridad","Disponibilidad"],"items":[["«Siempre se corta la luz un rato, no va a pasar nada.»",1],["«El jefe dijo que no evacuemos, así que no evacuamos.»",2],["«La semana pasada fue un simulacro, seguro esto también lo es.»",3],["«Yo sabía que era el proveedor», e ignorar los datos que dicen otra cosa.",0]],"exp":"Para contrarrestar los sesgos: contrastar información y escuchar otras perspectivas."},{"t":"mc","id":"c2-3","p":"¿Qué criterio debe guiar las decisiones en los primeros minutos?","ops":["Proteger la imagen de la empresa","Proteger a las personas, contener el daño y sostener funciones críticas","Encontrar al culpable","Esperar toda la información antes de actuar"],"ok":1,"exp":"Primero las personas, luego contener el daño y sostener funciones críticas. Las decisiones se revisan con seguimiento y ajuste."}]},{"id":"comunicar","estacion":"Comunicar","titulo":"Hablar bajo presión","minutos":6,"intro":"Los 8 principios de la comunicación en crisis y los errores más comunes.","pasos":[{"t":"tarjetas","cartas":[["8 principios","Oportunidad, veracidad, claridad, coherencia, empatía, prudencia, continuidad y responsabilidad."],["Mensaje clave","Responde: ¿qué ocurrió?, ¿qué se está haciendo?, ¿qué deben hacer las personas? y ¿cuándo habrá nueva información?"],["Vocería","Persona autorizada que comunica la posición oficial, con mensajes coherentes y coordinados."],["Interna vs. externa","Interna: equipos y jefaturas. Externa: usuarios, comunidad, medios y autoridades. Distinto detalle, pero nunca contradictorias."],["Rumores","Flujo: monitorear, verificar, priorizar, responder por canales oficiales y actualizar. No reaccionar a cada publicación."],["6 errores frecuentes","Silencio prolongado, información no verificada, minimizar («no pasa nada»), lenguaje técnico, falta de empatía, contradicciones o promesas sin certeza."]]},{"t":"mc","id":"c2-4","p":"Una falla interrumpe la atención y la causa aún se verifica. ¿Qué mensaje inicial es más adecuado?","ops":["«Todo está controlado; volverá pronto.»","«No informaremos hasta conocer la causa.»","«Detectamos una interrupción, activamos equipos técnicos y actualizaremos a las 12:00 por el canal oficial.»","«La falla se debe al proveedor.»"],"ok":2,"exp":"Reconoce lo confirmado, informa una acción, no especula y compromete una actualización: veracidad, oportunidad, claridad, prudencia y continuidad."},{"t":"mc","id":"c2-5","p":"Verdadero o falso: solo se debe comunicar cuando se conocen todos los antecedentes.","ops":["Verdadero","Falso"],"ok":1,"exp":"Falso. Se emite un mensaje inicial con lo confirmado, lo que se está verificando y cuándo habrá una actualización."},{"t":"mc","id":"c2-6","p":"Un vocero da datos correctos, pero con lenguaje técnico y sin decir qué deben hacer los usuarios. ¿Qué principio falla?","ops":["Oportunidad","Claridad","Continuidad","Veracidad"],"ok":1,"exp":"Claridad: lenguaje simple e instrucciones concretas."},{"t":"mc","id":"c2-7","p":"Por radio te piden informar a los pasajeros del andén. ¿Qué mensaje usas?","ops":["«No pasa nada, tranquilos.»","«Hay una falla en el sistema; el tren viene con atraso. Por seguridad manténganse detrás de la línea amarilla. Informaremos de nuevo en 10 minutos.»","«Parece que hubo un accidente más adelante.»","No dices nada hasta que llegue el tren"],"ok":1,"exp":"Dice qué ocurre (lo confirmado), qué hacer y cuándo habrá novedades. Las demás minimizan, especulan o dejan un silencio que alimenta rumores."}]}]},{"id":"CEMCG0401-L3","codigo":"CEMCG0401","curso":"Manejo de Crisis y Emergencias","etiqueta":"Lección","semana":3,"titulo":"Fundamentos de la gestión de emergencias","desde":"2026-11-05","hasta":"2026-11-30","entregas":[],"misiones":[{"id":"fases","estacion":"Fases","titulo":"Antes, durante y después","minutos":5,"intro":"Preparación, respuesta y recuperación forman un ciclo continuo.","pasos":[{"t":"tarjetas","cartas":[["Preparación (antes)","Planes, capacitación, simulacros, roles, recursos, sistemas de alerta y coordinación previa."],["Respuesta (durante)","Evacuar, aislar áreas, atención inicial, comunicar instrucciones, coordinar y pedir apoyo."],["Recuperación (después)","Evaluar daños, reponer servicios, apoyar a los afectados, revisar procedimientos y aprender."],["El ciclo","Una buena preparación mejora la respuesta; una respuesta oportuna reduce daños; una recuperación evaluada permite aprender."]]},{"t":"clasificar","id":"c3-1","p":"¿En qué fase va cada acción?","cats":["Preparación","Respuesta","Recuperación"],"items":[["Simulacro de evacuación de la estación",0],["Evacuar el andén por una fuga de gas",1],["Revisar qué falló y actualizar el plan",2],["Definir quién coordina y quién comunica",0],["Pedir apoyo a Bomberos",1],["Reponer el servicio y apoyar a los afectados",2]],"exp":"Preparación: antes. Respuesta: durante o justo al inicio. Recuperación: restablecer y aprender."},{"t":"mc","id":"c3-2","p":"Durante una fuga de gas en una instalación, ¿qué acción corresponde a la respuesta?","ops":["Actualizar el plan anual de emergencias","Activar el procedimiento, proteger a las personas, evacuar y coordinar apoyo especializado","Evaluar los aprendizajes después","Rediseñar procedimientos"],"ok":1,"exp":"Es la actividad oficial de la lección 3."}]},{"id":"componentes","estacion":"Organizar","titulo":"Componentes y principios","minutos":6,"intro":"Los 7 componentes para organizar la respuesta y los 7 principios de actuación.","pasos":[{"t":"tarjetas","cartas":[["7 componentes","1 Identificación de amenazas · 2 Roles y responsabilidades · 3 Planes y protocolos · 4 Recursos · 5 Comunicación y alerta · 6 Coordinación interna y externa · 7 Registro y evaluación."],["7 principios de actuación","Protección de la vida · Oportunidad · Proporcionalidad · Coordinación · Comunicación responsable · Flexibilidad y adaptación · Ética y responsabilidad institucional."],["Proporcionalidad","Ajustar la magnitud de la respuesta al nivel real de riesgo, afectación y capacidad."],["Plan de emergencia","Define escenarios, organización, responsabilidades, recursos y procedimientos para emergencias previsibles."]]},{"t":"mc","id":"c3-3","p":"¿Qué principio debe orientar cualquier acción frente a un evento adverso?","ops":["Proteger los bienes de la empresa","La protección de la vida y la seguridad de las personas","Mantener la reputación","Cumplir los horarios"],"ok":1,"exp":"Está por sobre intereses materiales, económicos, reputacionales o administrativos."},{"t":"mc","id":"c3-4","p":"¿Por qué se definen roles ANTES de una emergencia?","ops":["Para tener a quién culpar","Para que cada uno sepa qué hacer y a quién reportar, sin confusión, duplicidades ni retrasos","Porque lo exige el reglamento interno","No hace falta, se define en el momento"],"ok":1,"exp":"Es una de las preguntas de aplicación de la infografía."},{"t":"clasificar","id":"c3-5","p":"¿Organización preparada o no preparada?","cats":["Preparada","No preparada"],"items":[["Realiza simulacros",0],["Improvisa acciones",1],["Tiene roles definidos",0],["Responde tarde",1],["Mantiene recursos disponibles",0],["Comunica de forma poco clara",1]],"exp":"La preparación reduce la improvisación; la respuesta oportuna reduce el impacto."}]}]},{"id":"CEMCG0401-L4","codigo":"CEMCG0401","curso":"Manejo de Crisis y Emergencias","etiqueta":"Lección","semana":4,"titulo":"Criterios básicos de actuación","desde":"2026-11-06","hasta":"2026-11-30","entregas":[{"nombre":"Evaluación final (cuestionario, 38 pts, 1 intento, 2 h)","vence":"2026-11-30T23:59:00-03:00","mision":"simulacro"}],"misiones":[{"id":"criterios","estacion":"Criterios","titulo":"Proteger, priorizar, comunicar","minutos":5,"intro":"Cómo pasar del análisis a acciones iniciales coherentes.","pasos":[{"t":"tarjetas","cartas":[["7 criterios generales","Proteger a las personas · Reconocer la situación · Usar la información disponible · Priorizar · Comunicar responsablemente · Coordinar · Registrar y aprender."],["Orden de prioridades","Primero proteger a las personas; luego contener el daño, sostener funciones críticas y coordinar recursos."],["Acción inicial coherente","Pertinente, oportuna, proporcional, factible, coordinada y comunicada."],["Coordinación · comunicación · apoyo","Coordinación organiza responsabilidades; comunicación orienta a las personas; apoyo operativo ejecuta acciones concretas."]]},{"t":"orden","id":"c4-1","p":"Ordena la secuencia para proponer acciones iniciales.","items":["Describir la situación","Identificar riesgos","Definir acciones iniciales","Asignar responsables","Establecer seguimiento"],"exp":"Es la actividad 4 del interactivo de la lección 4. Evita respuestas vagas."},{"t":"mc","id":"c4-2","p":"Caída total del sistema en una institución pública, con usuarios molestos y publicaciones en redes. ¿Qué priorizas en los primeros minutos?","ops":["Buscar responsables antes de informar","Confirmar alcance, activar soporte, orientar a funcionarios y comunicar un mensaje inicial prudente","Guardar silencio hasta resolverlo","Publicar una causa definitiva sin verificar"],"ok":1,"exp":"Proteger la continuidad, reducir la incertidumbre, coordinar equipos y comunicar con responsabilidad."},{"t":"clasificar","id":"c4-3","p":"Une cada concepto con su función.","cats":["Coordinación","Comunicación","Apoyo operativo"],"items":[["Organiza responsabilidades",0],["Orienta a las personas",1],["Ejecuta acciones concretas",2]],"exp":"Sin coordinación hay duplicidades; sin comunicación, incertidumbre; sin apoyo, las decisiones no se ejecutan."}]},{"id":"simulacro","estacion":"Simulacro","titulo":"Ensayo de la evaluación final","minutos":8,"intro":"Preguntas mezcladas de las 4 lecciones, al estilo del cuestionario final (38 pts, un solo intento).","pasos":[{"t":"mc","id":"c4-s1","p":"¿Qué distingue a una crisis de una emergencia?","ops":["La crisis siempre tiene heridos","La crisis amenaza la estabilidad, continuidad, confianza o legitimidad de la organización","La emergencia dura más","No hay diferencia"],"ok":1,"exp":"La emergencia es un peligro que exige respuesta inmediata; la crisis afecta la estabilidad y confianza de la organización. Una puede derivar en la otra."},{"t":"mc","id":"c4-s2","p":"«Se comenta que hubo heridos» circula por WhatsApp sin fuente. ¿Cómo lo tratas?","ops":["Lo comunicas de inmediato por si acaso","Información no verificada: la monitoreas y verificas, sin comunicarla como hecho","Lo desmientes públicamente sin revisar","Lo ignoras por completo"],"ok":1,"exp":"Flujo ante rumores: monitorear, verificar, priorizar, responder por canal oficial y actualizar."},{"t":"mc","id":"c4-s3","p":"Evaluar daños y actualizar procedimientos después de un evento corresponde a…","ops":["Preparación","Respuesta","Recuperación","Alerta"],"ok":2,"exp":"La recuperación restablece servicios y deja aprendizaje."},{"t":"mc","id":"c4-s4","p":"«Antes nunca pasó nada grave con las lluvias.» ¿Qué sesgo es?","ops":["Confirmación","Normalidad","Autoridad","Disponibilidad"],"ok":1,"exp":"El sesgo de normalidad subestima el riesgo porque antes no fue grave."},{"t":"mc","id":"c4-s5","p":"Ajustar la magnitud de la respuesta al nivel real de riesgo es el principio de…","ops":["Oportunidad","Proporcionalidad","Flexibilidad","Coherencia"],"ok":1,"exp":"Proporcionalidad: ni sobrerreaccionar ni quedarse corto."},{"t":"mc","id":"c4-s6","p":"¿Qué preguntas responde un mensaje clave?","ops":["Quién tuvo la culpa y cuánto costó","Qué ocurrió, qué se está haciendo, qué deben hacer las personas y cuándo habrá nueva información","Solo qué ocurrió","Cuál es la causa definitiva"],"ok":1,"exp":"Esa es la estructura del mensaje clave según el glosario y la lección 2."},{"t":"mc","id":"c4-s7","p":"Una crisis que aparece de golpe, como un accidente grave, se llama…","ops":["Progresiva","Súbita","Reputacional","Organizacional"],"ok":1,"exp":"Súbita: poco tiempo para prepararse e información inicial limitada."},{"t":"mc","id":"c4-s8","p":"Registrar decisiones, horarios y responsables durante la respuesta sirve para…","ops":["Sancionar a los trabajadores","Dar trazabilidad, ajustar la respuesta y aprender después","Cumplir un trámite sin uso","Reemplazar la comunicación"],"ok":1,"exp":"Registro y trazabilidad: seguimiento, rendición de cuentas y mejora."},{"t":"mc","id":"c4-s9","p":"Verdadero o falso: la primera acción ante una crisis siempre debe ser comunicar públicamente una solución definitiva.","ops":["Verdadero","Falso"],"ok":1,"exp":"Falso. Se comunica con prudencia lo confirmado; anunciar soluciones sin verificar aumenta rumores y daña la confianza."},{"t":"mc","id":"c4-s10","p":"Una crisis se extiende varios días y el equipo está agotado. ¿Qué corresponde?","ops":["Que el mismo equipo siga hasta terminar","Organizar turnos, descansos y relevos","Suspender la comunicación","Esperar que termine sola"],"ok":1,"exp":"La fatiga afecta concentración y juicio; la continuidad exige relevos."}]}]},{"id":"ESTAP1204-S1","codigo":"ESTAP1204","curso":"Estadística Aplicada","semana":1,"titulo":"Conceptos básicos y tablas de frecuencia","desde":"2026-11-03","hasta":"2026-11-09","entregas":[],"misiones":[{"id":"inicio","estacion":"Inicio","titulo":"¿Para qué sirve la estadística?","minutos":3,"intro":"Lo que contó el ingeniero del podcast de la semana.","pasos":[{"t":"lectura","titulo":"La idea central","texto":["La estadística descriptiva representa un conjunto de datos en números, tablas y gráficos para interpretarlo o pronosticar un evento.","El método tiene tres pasos: recolectar la información, ordenarla y luego tabular y graficar para analizar.","En la industria sirve para detectar fallas, mejorar la calidad y pronosticar la demanda. En prevención, para saber dónde y cuándo ocurren los incidentes."]},{"t":"orden","id":"e1-i1","p":"Ordena los pasos del método estadístico.","items":["Recolectar la información","Ordenar los datos recopilados","Tabular y graficar","Interpretar y analizar"],"exp":"Primero se junta la información, después se ordena, luego se resume en tablas y gráficos y al final se interpreta."}]},{"id":"conceptos","estacion":"Conceptos","titulo":"Población, muestra y variable","minutos":5,"intro":"La base de cualquier estudio, y la pregunta 1 de la tarea.","pasos":[{"t":"tarjetas","cartas":[["Población","Conjunto de todos los elementos en estudio. Puede ser finita o infinita."],["Censo","Observar a toda la población. Suele ser caro y lento; por eso se usan muestras."],["Muestra","Subconjunto de la población que intenta conservar sus características."],["Variable","La característica que se quiere estudiar de cada elemento."],["Cuantitativa discreta","Cantidad que se cuenta: número de hijos, televisores, incidentes."],["Cuantitativa continua","Cantidad que se mide y puede tener decimales: sueldo, peso, minutos de atraso, lluvia caída."],["Cualitativa nominal","Una cualidad sin orden: color, especie, tipo de calzado, profesión."],["Cualitativa ordinal","Una cualidad con orden: nivel educacional, cargo jerárquico, nivel de riesgo bajo-medio-alto."]]},{"t":"mc","id":"e1-c1","p":"EFE quiere saber qué opinan los pasajeros de Puerto Montt y encuesta a 150 en una semana. ¿Cuál es la muestra?","ops":["Todos los pasajeros de la estación","Los 150 pasajeros encuestados","La opinión de cada pasajero","La estación"],"ok":1,"exp":"La población son todos los pasajeros de la estación. La muestra son los 150 encuestados. La opinión es la variable."},{"t":"clasificar","id":"e1-c2","p":"Clasifica cada variable.","cats":["Cualitativa nominal","Cualitativa ordinal","Cuantitativa discreta","Cuantitativa continua"],"items":[["Tipo de incidente (robo, caída, riña)",0],["Nivel de riesgo: bajo, medio, alto",1],["Número de incidentes por turno",2],["Tiempo de respuesta en minutos",3],["Color del uniforme",0],["Peso de una maleta",3],["Pasajeros que pasan por el torniquete",2]],"exp":"¿Se cuenta? Es discreta. ¿Se mide y admite decimales? Es continua. ¿Es una palabra con orden? Es ordinal; sin orden, nominal."},{"t":"lectura","titulo":"Ojo con un ejemplo del material","texto":["En la lista de variables nominales el material incluye \"edad\". Es un error: la edad es cuantitativa, porque es una cantidad. El mismo material la pone después como ejemplo de cuantitativa.","Solo sería cualitativa ordinal si se agrupa en tramos como \"joven\", \"adulto\" y \"adulto mayor\"."]}]},{"id":"tabla","estacion":"Tabla de frecuencias","titulo":"fi, Fi, hi, Hi","minutos":6,"intro":"Los cuatro elementos de la tabla. Ten lápiz a mano.","pasos":[{"t":"tarjetas","cartas":[["fi: frecuencia absoluta","Cuántas veces se repite un dato. La suma de todas las fi es n."],["Fi: absoluta acumulada","Suma de las fi hasta esa fila, incluida. La última Fi es n."],["hi: relativa porcentual","hi = fi / n × 100. El porcentaje de cada fila."],["Hi: relativa acumulada","Suma de las hi hasta esa fila. La última Hi es 100 %."]]},{"t":"lectura","titulo":"Los datos","texto":["Incidentes registrados en 12 turnos de la estación: 0, 1, 1, 2, 0, 3, 1, 2, 1, 0, 1, 2.","Conteo: 0 incidentes → 3 turnos. 1 → 5 turnos. 2 → 3 turnos. 3 → 1 turno."]},{"t":"mc","id":"e1-t1","p":"¿Cuál es la Fi (acumulada) de la fila \"2 incidentes\"?","ops":["3","8","11","12"],"ok":2,"exp":"3 + 5 + 3 = 11. Once turnos tuvieron 2 incidentes o menos."},{"t":"mc","id":"e1-t2","p":"¿Cuál es la hi de la fila \"1 incidente\"?","ops":["5 %","41,7 %","50 %","66,7 %"],"ok":1,"exp":"5 / 12 × 100 = 41,7 %."},{"t":"mc","id":"e1-t3","p":"¿Cuál es la Hi de la fila \"1 incidente\"?","ops":["41,7 %","25 %","66,7 %","91,7 %"],"ok":2,"exp":"25 % + 41,7 % = 66,7 %. Dos tercios de los turnos tuvieron 1 incidente o menos."},{"t":"mc","id":"e1-t4","p":"Ejemplo del material: 16 alumnos, 3 tienen 3 computadores. ¿Cuál es la hi?","ops":["18,75 %","3 %","31,25 %","75 %"],"ok":0,"exp":"3 / 16 × 100 = 18,75 %. El material la redondea a 18,7 % (y en un cálculo aparece mal escrito como 18,37 %)."}]},{"id":"agrupados","estacion":"Intervalos","titulo":"Sturges y la amplitud","minutos":5,"intro":"Qué hacer cuando hay muchos datos continuos.","pasos":[{"t":"tarjetas","cartas":[["¿Cuándo agrupar?","Con variables continuas y muchos datos: se agrupan en intervalos o clases."],["Regla de Sturges","k = 1 + 3,3 × log(n). k es el número de intervalos y n el total de datos."],["Amplitud","A = (máximo − mínimo) / k. Se aproxima al número siguiente."],["Construir intervalos","El primero parte en el mínimo. Cada límite superior es el inferior más la amplitud."],["Excel","=CONTAR(), =MAX(), =MIN(), =REDONDEAR(1+3,3*LOG(n);0) y =CONTAR.SI.CONJUNTO() para contar por intervalo."]]},{"t":"mc","id":"e1-g1","p":"Con 40 datos, Sturges da k = 1 + 3,3 × log(40) = 6,29. ¿Cuántos intervalos usas?","ops":["6","7","40","3"],"ok":0,"exp":"Se redondea a 6, como en el ejemplo de las ganancias del material."},{"t":"mc","id":"e1-g2","p":"En ese ejemplo, el máximo es 309 y el mínimo 212. ¿Cuál es la amplitud?","ops":["16","17","97","6"],"ok":1,"exp":"(309 − 212) / 6 = 16,17. Se aproxima al entero siguiente: 17."},{"t":"mc","id":"e1-g3","p":"Si el primer intervalo empieza en 212 y la amplitud es 17, ¿cuál es el segundo intervalo?","ops":["[212, 229)","[229, 246)","[230, 247)","[246, 263)"],"ok":1,"exp":"212 + 17 = 229, que cierra el primero y abre el segundo. 229 + 17 = 246."},{"t":"mc","id":"e1-g4","p":"Tienes 30 datos. Con Sturges, k = 1 + 3,3 × log(30) ≈ 5,87. ¿Cuántos intervalos?","ops":["5","6","30","4"],"ok":1,"exp":"5,87 se redondea a 6."}]},{"id":"graficos","estacion":"Gráficos","titulo":"El gráfico correcto para cada variable","minutos":4,"intro":"Torta, histograma y polígono de frecuencias.","pasos":[{"t":"tarjetas","cartas":[["Gráfico circular (torta)","Sobre todo para variables cualitativas. Usa fi o hi."],["Histograma","Barras sin separación. La superficie de cada barra es proporcional a la frecuencia. Para datos agrupados en clases."],["Polígono de frecuencias","Para cuantitativas, sobre todo continuas. Une los puntos medios de cada intervalo."],["Histograma en Excel","Insertar → gráfico de columnas → Formato de serie → ancho del intervalo al mínimo, para que no queden espacios."],["Infostat","Software estadístico gratuito para Windows, compatible con Excel. Se descarga de infostat.com.ar."]]},{"t":"clasificar","id":"e1-f1","p":"¿Qué gráfico usarías?","cats":["Circular","Histograma"],"items":[["Tipo de incidente en la estación",0],["Tiempos de respuesta agrupados en intervalos",1],["Medio de transporte de llegada a la estación",0],["Peso de las maletas revisadas",1]],"exp":"Cualitativas en torta y continuas agrupadas en histograma."},{"t":"mc","id":"e1-f2","p":"Barras donde la superficie de cada una es proporcional a la frecuencia. ¿Qué gráfico es?","ops":["Diagrama circular","Histograma","Espina de pescado","Polígono ojiva"],"ok":1,"exp":"Es el histograma, la microactividad 2 del interactivo."},{"t":"mc","id":"e1-f3","p":"¿Qué programa estadístico gratuito recomienda la asignatura?","ops":["SPSS","Adobe","Infostat","Excel"],"ok":2,"exp":"Infostat, en su versión libre. Lo vas a usar en todas las tareas."}]},{"id":"anden","estacion":"Caso en el andén","titulo":"Tu libro de novedades en números","minutos":4,"intro":"Cómo convertir lo que anotas en el turno en información útil.","pasos":[{"t":"lectura","titulo":"Situación","texto":["En el libro de novedades anotas cada incidente: hora, tipo (caída, robo, riña, persona extraviada), sector del andén y minutos que tardaste en llegar.","La jefatura te pide resumir el último mes para decidir dónde poner cámaras."]},{"t":"clasificar","id":"e1-a1","p":"Clasifica las variables de tu registro.","cats":["Cualitativa","Cuantitativa discreta","Cuantitativa continua"],"items":[["Tipo de incidente",0],["Sector del andén",0],["Incidentes por día",1],["Minutos en llegar",2]],"exp":"Tipo y sector son cualidades. Contar incidentes da una discreta. El tiempo se mide, así que es continua."},{"t":"mc","id":"e1-a2","p":"Para decidir dónde poner cámaras, ¿qué tabla y gráfico conviene presentar?","ops":["Tabla de frecuencias por sector del andén, con un gráfico circular o de barras","Un histograma de la hora de cada incidente sin agrupar","Solo el total de incidentes","El promedio de minutos en llegar"],"ok":0,"exp":"La pregunta es dónde ocurren, así que la variable clave es el sector. Su hi te dice qué porcentaje de incidentes ocurre en cada uno."}]}]},{"id":"ESTAP1204-S2","codigo":"ESTAP1204","curso":"Estadística Aplicada","semana":2,"titulo":"Tendencia central y posición","desde":"2026-11-10","hasta":"2026-11-16","entregas":[],"misiones":[{"id":"inicio","estacion":"Inicio","titulo":"¿Dónde se juntan los datos?","minutos":3,"intro":"Las dos familias de medidas que vas a usar toda la semana.","pasos":[{"t":"lectura","titulo":"Dos preguntas distintas","texto":["Las medidas de tendencia central responden dónde se concentran los datos. Son tres: la media (el promedio), la mediana (el dato que divide el conjunto en dos mitades) y la moda (el valor que más se repite).","Las medidas de posición dividen los datos en grupos de igual tamaño: los cuartiles en 4 partes, los deciles en 10 y los percentiles en 100. Sirven para ubicar un dato dentro del total (por ejemplo, saber si un valor está entre el 25 % más bajo)."]},{"t":"clasificar","id":"e2-i1","p":"¿A qué familia pertenece cada medida?","cats":["Tendencia central","Posición"],"items":[["Media",0],["Cuartil",1],["Moda",0],["Percentil",1],["Mediana",0],["Decil",1]],"exp":"Tendencia central: media, mediana y moda. Posición: cuartiles, deciles y percentiles. Ojo: la mediana coincide con el cuartil 2 y el percentil 50, pero se estudia como tendencia central."}]},{"id":"conceptos","estacion":"Conceptos","titulo":"Media, mediana y moda","minutos":5,"intro":"Definiciones y fórmulas que aparecen en la tarea.","pasos":[{"t":"tarjetas","cartas":[["Media aritmética","El centro de gravedad de los datos: el promedio. Datos no agrupados: x̄ = Σxᵢ / n."],["Media para datos agrupados","x̄ = Σ(Mc · fᵢ) / n. Mc es la marca de clase y fᵢ la frecuencia absoluta."],["Marca de clase (Mc)","Punto medio del intervalo: (límite inferior + límite superior) / 2. En el intervalo 10–20 es 15."],["Mediana","Con los datos ordenados, deja 50 % abajo y 50 % arriba. Si n es impar es el dato central; si es par, el promedio de los dos centrales."],["Moda","El valor que más se repite. Puede haber más de una. En datos agrupados, la clase modal es el intervalo con más datos."],["Datos agrupados vs. no agrupados","Agrupados: en intervalos o clases (variable continua). No agrupados: valores contables uno a uno (variable discreta)."],["Cuartiles, deciles y percentiles","Cuartiles: 4 partes (Q1, Q2, Q3). Deciles: 10 partes. Percentiles: 100 partes (99 puntos de corte)."]]},{"t":"mc","id":"e2-c1","p":"En un conjunto de datos, ¿qué mide la moda?","ops":["El promedio de los datos","El valor que más se repite","El dato que deja la mitad abajo","La diferencia entre el máximo y el mínimo"],"ok":1,"exp":"La moda es el valor observado con mayor frecuencia."},{"t":"mc","id":"e2-c2","p":"Tienes 8 datos ordenados. ¿Cómo obtienes la mediana?","ops":["Tomas el 4.º dato","Tomas el 5.º dato","Promedias el 4.º y el 5.º dato","Promedias los 8 datos"],"ok":2,"exp":"Con n par hay dos datos centrales; la mediana es su promedio."},{"t":"mc","id":"e2-c3","p":"¿Cuál es la marca de clase del intervalo 20–30?","ops":["20","25","30","10"],"ok":1,"exp":"(20 + 30) / 2 = 25. Es el punto medio del intervalo."},{"t":"mc","id":"e2-c4","p":"¿En cuántas partes iguales dividen los datos los cuartiles?","ops":["2","4","10","100"],"ok":1,"exp":"Cuartil viene de cuatro: 4 partes, separadas por Q1, Q2 (la mediana) y Q3."}]},{"id":"calculo","estacion":"A mano","titulo":"Calcula sin calculadora","minutos":6,"intro":"Ejercicios cortos con datos de una estación de trenes. Ten lápiz y papel a mano.","pasos":[{"t":"lectura","titulo":"Los datos","texto":["Minutos de atraso de 8 trenes que llegaron a la estación en un día: 4, 0, 7, 3, 4, 12, 4, 2.","Ordenados de menor a mayor: 0, 2, 3, 4, 4, 4, 7, 12."]},{"t":"mc","id":"e2-m1","p":"¿Cuál es la media de atraso?","ops":["4 minutos","4,5 minutos","5 minutos","3,5 minutos"],"ok":1,"exp":"Suma = 0+2+3+4+4+4+7+12 = 36. Media = 36 / 8 = 4,5 minutos."},{"t":"mc","id":"e2-m2","p":"¿Cuál es la mediana?","ops":["4 minutos","3,5 minutos","4,5 minutos","7 minutos"],"ok":0,"exp":"n = 8 (par). Los centrales son el 4.º y el 5.º: 4 y 4. Mediana = (4 + 4) / 2 = 4."},{"t":"mc","id":"e2-m3","p":"¿Cuál es la moda?","ops":["0","12","4","No hay moda"],"ok":2,"exp":"El 4 aparece 3 veces; ningún otro valor se repite tanto."},{"t":"mc","id":"e2-m4","p":"Otro día los atrasos fueron 2, 3, 3, 4, 5, 6 y 48 (un tren con falla). ¿Qué medida representa mejor un atraso típico?","ops":["La media (10,1 min), porque usa todos los datos","La mediana (4 min), porque el 48 la afecta poco","El máximo (48 min)","Ninguna sirve"],"ok":1,"exp":"Un valor extremo arrastra la media hacia arriba (10,1). La mediana queda en 4, que sí representa a la mayoría de los trenes."},{"t":"mc","id":"e2-m5","p":"Datos agrupados: atrasos de 0–10 min (12 trenes), 10–20 min (20 trenes) y 20–30 min (8 trenes). ¿Cuál es la media?","ops":["15 minutos","14 minutos","13,3 minutos","20 minutos"],"ok":1,"exp":"Marcas de clase: 5, 15 y 25. Σ(Mc·fᵢ) = 5·12 + 15·20 + 25·8 = 60 + 300 + 200 = 560. n = 40. Media = 560 / 40 = 14 min."}]},{"id":"infostat","estacion":"Infostat","titulo":"El software paso a paso","minutos":5,"intro":"El interactivo de la semana usa Infostat. Practica el procedimiento y la lectura de resultados.","pasos":[{"t":"orden","id":"e2-s1","p":"Ordena los pasos para obtener las medidas de resumen en Infostat.","items":["Archivo → Nueva tabla y pegar los datos","Estadísticas → Medidas de resumen","Seleccionar la columna y pasarla a Variables con la flecha","Marcar lo que quieres calcular (n, media, mediana, Q1, Q3…)","Aceptar y leer la tabla de resultados"],"exp":"Mismo procedimiento del material: nueva tabla, Estadísticas, Medidas de resumen, elegir variable, marcar medidas y aceptar."},{"t":"mc","id":"e2-s2","p":"Las calificaciones de 15 estudiantes son 7, 8, 9, 9, 9, 9, 7, 8, 7, 7, 7, 8, 5, 9, 7. ¿Qué media entrega Infostat?","ops":["7,73","9","5,2","8,5"],"ok":0,"exp":"Suma = 116. 116 / 15 = 7,73. Es la microactividad 2 del interactivo."},{"t":"mc","id":"e2-s3","p":"Con esas mismas 15 calificaciones, ¿cuál es Q1?","ops":["7,5","7","7,8","8"],"ok":1,"exp":"Ordenadas: 5, 7, 7, 7, 7, 7, 7, 8, 8, 8, 9, 9, 9, 9, 9. El 25 % más bajo llega hasta 7. Es la microactividad 3."},{"t":"mc","id":"e2-s4","p":"En el ejemplo de las 40 temperaturas de Santiago, Infostat dio Q1 = 16 y Q3 = 18. ¿Qué significa Q3 = 18?","ops":["Que el 75 % de los días tuvo 18 °C o menos","Que 18 °C fue la temperatura más repetida","Que el promedio fue 18 °C","Que 3 días tuvieron 18 °C"],"ok":0,"exp":"Q3 deja el 75 % de los datos por debajo. En ese ejemplo la media fue 17,48 y la mediana 17."},{"t":"mc","id":"e2-s5","p":"¿Qué gráfico de Infostat muestra mínimo, Q1, mediana, Q3 y máximo de un vistazo?","ops":["Gráfico de torta","Box plot (gráfico de caja)","Histograma","Gráfico de líneas"],"ok":1,"exp":"En el box plot la caja va de Q1 a Q3, la línea interior es la mediana y los bigotes llegan al mínimo y al máximo."}]},{"id":"anden","estacion":"Caso en el andén","titulo":"Los números de tu turno","minutos":4,"intro":"Estadística aplicada a prevención: datos que podrías levantar en tu propio trabajo.","pasos":[{"t":"lectura","titulo":"Situación","texto":["La jefatura de seguridad quiere saber cuántos pasajeros pasan por el control de acceso en la hora punta de la mañana. Registraste 7 días: 120, 95, 140, 110, 95, 130 y 150 pasajeros.","Ordenados: 95, 95, 110, 120, 130, 140, 150."]},{"t":"mc","id":"e2-a1","p":"¿Cuál es la mediana de pasajeros?","ops":["110","120","130","95"],"ok":1,"exp":"n = 7 (impar): el dato central es el 4.º, que es 120."},{"t":"mc","id":"e2-a2","p":"¿Y la moda?","ops":["95","120","150","No hay"],"ok":0,"exp":"95 aparece dos veces; el resto, una vez."},{"t":"mc","id":"e2-a3","p":"La media también da 120. Para decidir cuántos guardias poner en hora punta, ¿qué conviene informar además del promedio?","ops":["Solo la media","El máximo o un percentil alto (por ejemplo P90), para cubrir los días más cargados","La moda, porque es el valor más bajo","Nada más"],"ok":1,"exp":"En prevención se dimensiona para los días exigentes, no solo para el promedio. Las medidas de posición altas (Q3, P90, máximo) muestran cuánta carga hay que cubrir."}]}]},{"id":"ESTAP1204-S3","codigo":"ESTAP1204","curso":"Estadística Aplicada","semana":3,"titulo":"Medidas de dispersión","desde":"2026-11-17","hasta":"2026-11-23","entregas":[{"nombre":"Tarea semana 3 (Unidad 1)","vence":"2026-11-23T23:59:00-03:00","mision":"taller"}],"misiones":[{"id":"inicio","estacion":"Inicio","titulo":"Mismo promedio, distinta historia","minutos":3,"intro":"Por qué el promedio solo no basta.","pasos":[{"t":"lectura","titulo":"Dos turnos de guardia","texto":["Se midió cuántos minutos tarda cada turno en responder una alarma en la estación. Seis alarmas por turno.","Turno A: 3, 5, 4, 6, 2, 4. Turno B: 1, 9, 2, 8, 3, 1.","Los dos turnos promedian 4 minutos. Pero el turno A siempre llega más o menos igual, y en el B nunca se sabe. Esa diferencia es la dispersión: qué tan juntos o separados están los datos respecto a la media."]},{"t":"mc","id":"e3-i1","p":"¿Qué turno tiene tiempos más homogéneos?","ops":["El turno A","El turno B","Son iguales porque tienen el mismo promedio","No se puede saber"],"ok":0,"exp":"Los datos del A están cerca de 4; los del B van de 1 a 9. Mismo promedio, distinta dispersión."},{"t":"mc","id":"e3-i2","p":"Las medidas de dispersión son un complemento de...","ops":["Las medidas de tendencia central","Los gráficos de torta","Las variables cualitativas","La población"],"ok":0,"exp":"La media dice dónde está el centro; la dispersión dice qué tan representativo es ese centro."}]},{"id":"conceptos","estacion":"Conceptos","titulo":"Rango, varianza y desviación","minutos":5,"intro":"Las definiciones del material y lo que aparece en la tarea.","pasos":[{"t":"tarjetas","cartas":[["Dispersión","Qué tan homogéneos (iguales) o heterogéneos (diferentes) son los datos."],["Rango o recorrido","Máximo − mínimo. Simple y rápido, pero sensible a valores extremos."],["Rango en datos agrupados","Límite superior del último intervalo − límite inferior del primero."],["Varianza","Promedio de los cuadrados de las diferencias entre cada dato y la media. Sale en unidades al cuadrado."],["Desviación estándar (S)","Raíz cuadrada de la varianza. Vuelve a las unidades originales de los datos."],["Dispersión absoluta","Rango, varianza y desviación estándar: en las unidades de la variable."],["Dispersión relativa","No depende de las unidades. Se expresa en porcentaje, como el coeficiente de variación."],["Coeficiente de variación (CV)","CV = S / media × 100. Sirve para comparar la estabilidad de grupos con distinta media o unidad."]]},{"t":"clasificar","id":"e3-c1","p":"¿Absoluta o relativa?","cats":["Dispersión absoluta","Dispersión relativa"],"items":[["Rango",0],["Varianza",0],["Desviación estándar",0],["Coeficiente de variación",1]],"exp":"El CV es relativo porque divide por la media y queda en porcentaje. Las otras tres van en las unidades de la variable (la varianza, al cuadrado)."},{"t":"mc","id":"e3-c2","p":"¿Por qué existe la desviación estándar si ya tenemos la varianza?","ops":["Porque la varianza queda en unidades al cuadrado y la desviación vuelve a la unidad original","Porque la varianza siempre da negativa","Porque son lo mismo","Porque la desviación ignora la media"],"ok":0,"exp":"Si los datos son minutos, la varianza queda en minutos². La desviación vuelve a minutos, así se puede interpretar."},{"t":"mc","id":"e3-c3","p":"Si la desviación estándar es 3, ¿cuánto vale la varianza?","ops":["9","1,73","6","3"],"ok":0,"exp":"La desviación es la raíz de la varianza, así que la varianza es 3² = 9."},{"t":"lectura","titulo":"Ojo con una frase del material","texto":["El organizador gráfico dice que \"la varianza no puede ser mayor que la media aritmética\". Eso no se cumple siempre.","Ejemplo: los datos 0 y 100 tienen media 50 y varianza 2.500. En la tarea no uses esa frase como regla para revisar tus resultados. Si te sale una varianza mayor que la media, puede estar bien."]}]},{"id":"calculo","estacion":"A mano","titulo":"Calcula paso a paso","minutos":7,"intro":"Datos chicos para entender qué hace el software por dentro. Ten lápiz a mano.","pasos":[{"t":"lectura","titulo":"Muestra o población","texto":["Hay dos versiones de la varianza. Poblacional: se divide por n. Muestral: se divide por n − 1.","Infostat las muestra como Var(n) y Var(n-1). En Excel son VAR.P y VAR.S; para la desviación, DESVEST.P y DESVEST.M. Si trabajas con una muestra, como en la tarea, usa la versión muestral (n − 1)."],"fuente":"Ayuda de funciones estadísticas de Microsoft Excel (VAR.S, VAR.P, DESVEST.M, DESVEST.P)."},{"t":"mc","id":"e3-m1","p":"Calificaciones: 2, 4, 2, 7, 9, 9, 5, 8. ¿Cuál es el rango?","ops":["9","7","5","2"],"ok":1,"exp":"Máximo 9 − mínimo 2 = 7. Es el ejemplo del material."},{"t":"lectura","titulo":"Varianza de 2, 4, 6, 8","texto":["Media = (2 + 4 + 6 + 8) / 4 = 5.","Diferencias con la media: −3, −1, 1, 3. Al cuadrado: 9, 1, 1, 9. Suma = 20."]},{"t":"mc","id":"e3-m2","p":"Con esa suma de 20, ¿cuál es la varianza muestral (n − 1)?","ops":["5","6,67","20","4"],"ok":1,"exp":"20 / (4 − 1) = 6,67. La poblacional sería 20 / 4 = 5."},{"t":"mc","id":"e3-m3","p":"¿Y la desviación estándar muestral?","ops":["2,58","6,67","3,33","2,24"],"ok":0,"exp":"√6,67 = 2,58. La poblacional sería √5 = 2,24."},{"t":"mc","id":"e3-m4","p":"Ejemplo del material: 50 funcionarios, Σ(xᵢ²·fᵢ) = 74.365 y media = 38,3 cigarros. Con s² = Σ(xᵢ²·fᵢ)/n − x̄², ¿cuánto da la varianza?","ops":["20,41","38,3","1.487,3","4,52"],"ok":0,"exp":"74.365 / 50 = 1.487,3. 38,3² = 1.466,89. 1.487,3 − 1.466,89 = 20,41. La desviación es √20,41 ≈ 4,52 (el material la trunca a 4,51)."},{"t":"mc","id":"e3-m5","p":"Turno A (3, 5, 4, 6, 2, 4) y turno B (1, 9, 2, 8, 3, 1). ¿Cuál es el rango de cada uno?","ops":["A = 4 y B = 8","A = 6 y B = 9","A = 2 y B = 1","Ambos 4"],"ok":0,"exp":"A: 6 − 2 = 4. B: 9 − 1 = 8. El rango ya muestra que B es más disperso."}]},{"id":"software","estacion":"Excel e Infostat","titulo":"Que el software haga la cuenta","minutos":5,"intro":"Las fórmulas del interactivo y cómo leer los resultados.","pasos":[{"t":"clasificar","id":"e3-s1","p":"¿Qué calcula cada fórmula de Excel?","cats":["Rango","Varianza muestral","Desviación muestral"],"items":[["=MAX(A1:A20)-MIN(A1:A20)",0],["=VAR.S(A1:A20)",1],["=DESVEST.M(A1:A20)",2],["=VARA(A1:A20)",1],["=DESVESTA(A1:A20)",2]],"exp":"VARA y DESVESTA también son muestrales, pero cuentan textos y valores lógicos. Con datos solo numéricos dan lo mismo que VAR.S y DESVEST.M."},{"t":"mc","id":"e3-s2","p":"Las 15 calificaciones del interactivo (7, 8, 9, 9, 9, 9, 7, 8, 7, 7, 7, 8, 5, 9, 7). ¿Qué varianza entrega =VAR.S?","ops":["2","1,35","2,17","7"],"ok":1,"exp":"1,35. Es la microactividad 2. Con VAR.P daría 1,26."},{"t":"mc","id":"e3-s3","p":"¿Y qué desviación estándar entrega =DESVEST.M?","ops":["1,58","7","1,16","2"],"ok":2,"exp":"√1,35 ≈ 1,16. Microactividad 3."},{"t":"orden","id":"e3-s4","p":"Ordena el procedimiento en Infostat para obtener la dispersión.","items":["Archivo → Nueva tabla e ingresar los datos","Estadísticas → Medidas de resumen","Pasar la variable a Variables con la flecha","Marcar Mín, Máx, Var(n-1) y D.E.","Aceptar y capturar la tabla de resultados"],"exp":"Es el mismo camino de la semana pasada; solo cambian las medidas que marcas."},{"t":"mc","id":"e3-s5","p":"200 sueldos de una minera: Excel da una desviación muestral de 88,42 miles de pesos. ¿Cómo se interpreta?","ops":["Los sueldos se alejan de la media, en promedio, unos 88 mil pesos","El sueldo promedio es 88 mil pesos","El 88 % gana lo mismo","Hay 88 sueldos distintos"],"ok":0,"exp":"La desviación es la distancia típica de los datos a la media, en la misma unidad que los datos."}]},{"id":"cv","estacion":"Comparar","titulo":"¿Quién es más estable?","minutos":4,"intro":"El coeficiente de variación compara grupos con medias o unidades distintas.","pasos":[{"t":"mc","id":"e3-v1","p":"Turno A: media 4 min y S = 1,41. Turno B: media 4 min y S = 3,58. ¿Cuál es el CV de cada uno?","ops":["A = 35,4 % y B = 89,4 %","A = 1,41 % y B = 3,58 %","A = 4 % y B = 4 %","A = 89,4 % y B = 35,4 %"],"ok":0,"exp":"CV = S / media × 100. A: 1,41 / 4 × 100 ≈ 35,4 %. B: 3,58 / 4 × 100 ≈ 89,4 %. B es mucho menos estable."},{"t":"mc","id":"e3-v2","p":"Pasajeros por hora: media 120 y S = 15. Atrasos de trenes: media 5 min y S = 3. ¿Cuál variable es más estable en términos relativos?","ops":["Pasajeros (CV = 12,5 %)","Atrasos (CV = 60 %)","Atrasos, porque su S es menor","No se pueden comparar"],"ok":0,"exp":"La S de los atrasos es menor, pero relativa a su media es enorme. Por eso se usa el CV para comparar."},{"t":"mc","id":"e3-v3","p":"Una meta dice que el 90 % de las respuestas debe ser en 6 minutos o menos. ¿Qué te dice mejor si se cumple?","ops":["Solo la media","El percentil 90 comparado con los 6 minutos","La moda","El CV"],"ok":1,"exp":"Si el P90 es 6 o menos, el 90 % de los datos está bajo la meta. La dispersión explica por qué la media sola puede engañar."}]},{"id":"anden","estacion":"Caso en el andén","titulo":"El informe para la jefatura","minutos":4,"intro":"Dispersión aplicada a decisiones de seguridad en la estación.","pasos":[{"t":"lectura","titulo":"Situación","texto":["La jefatura de seguridad de EFE quiere decidir qué turno necesita refuerzo. Tienes los tiempos de respuesta a alarmas del turno A (3, 5, 4, 6, 2, 4) y del turno B (1, 9, 2, 8, 3, 1). Ambos promedian 4 minutos."]},{"t":"mc","id":"e3-a1","p":"¿Qué le dirías a la jefatura?","ops":["Que los turnos son iguales, porque el promedio es el mismo","Que el turno B es poco predecible: a veces responde en 1 minuto y a veces en 9, así que conviene revisar por qué","Que el turno A es más lento","Que no hay datos suficientes para decir nada"],"ok":1,"exp":"Mayor rango, desviación y CV en B. En seguridad, una respuesta impredecible es un riesgo aunque el promedio se vea bien."},{"t":"orden","id":"e3-a2","p":"Ordena un informe breve de dispersión.","items":["Describir los datos y su fuente","Entregar la media de cada grupo","Entregar rango, desviación estándar y CV","Comparar qué grupo es más estable","Hacer una recomendación concreta"],"exp":"Es la misma lógica que pide la pregunta 6 de la tarea: calcular, comparar y recomendar."},{"t":"mc","id":"e3-a3","p":"Una sola alarma del turno A tardó 25 minutos (el guardia estaba atendiendo un accidente). ¿Qué medida se ve más afectada?","ops":["El rango","La moda","La mediana","Ninguna"],"ok":0,"exp":"El rango solo usa el máximo y el mínimo, así que un valor extremo lo dispara. La media y la desviación también suben, pero la mediana casi no cambia."}]},{"id":"taller","estacion":"Taller de la tarea","titulo":"Tarea semana 3: AcuaSur","minutos":25,"intro":"Prepara la tarea de la Unidad 1: qué pide cada pregunta, qué evalúa el profe y cómo hacerlo en Infostat.","pasos":[{"t":"taller","caso":"AcuaSur (empresa ficticia) tiene 11 centros de cultivo de salmón en Los Lagos. En el semestre registró 286 órdenes de trabajo (OT) correctivas. La aseguradora exige que el 90 % de las reparaciones se cierre en 6 horas o menos. Te entregan una muestra aleatoria de 20 OT con: equipo, tipo de falla, turno (día o noche), repuestos usados y horas de reparación. Debes describir cuánto se demoran, qué tan estables son los tiempos y si se cumple la meta, procesando los datos en Infostat.","ia":"Esta tarea es nivel 2 de uso de IA. Se permite explicar conceptos, resolver dudas de Infostat y revisar redacción. NO se permite calcular medidas, construir tablas o gráficos ni interpretar los resultados del caso. Nunca entregues números calculados ni conclusiones sobre los datos de AcuaSur.","preguntas":[{"id":"q1","p":"1. Conceptos básicos: población y muestra con sus tamaños, clasificación de las 5 variables, justificación de \"repuestos usados\" y \"horas de reparación\", y una limitación de la muestra.","indicador":"Identifica conceptos básicos de estadística, a partir de la distinción entre población, muestra y variables.","pistas":["Población: todo lo que se quiere estudiar. Muestra: la parte que analizas. Busca ambos números en el enunciado","Las 4 categorías: cualitativa nominal, cualitativa ordinal, cuantitativa discreta y cuantitativa continua","Pregúntate: ¿se cuenta o se mide? ¿Puede tomar valores con decimales?","Para la limitación, piensa en el tamaño de la muestra y en un valor muy distinto al resto"]},{"id":"q2","p":"2. Tablas de frecuencia y gráficos en Infostat: tipo de falla (absoluta, relativa y porcentual), horas agrupadas en intervalos, gráfico de sectores, histograma y qué categoría e intervalo concentran más OT.","indicador":"Construye tablas de distribución de frecuencias y gráficos a partir de conjuntos de datos simples, considerando Infostat.","pistas":["Estadísticas → Frecuencias → variable → Aceptar","Para las horas, define 5 intervalos e informa cuántos usaste y su amplitud","Gráfico de sectores con Categorías en filas; histograma para las horas","Pega las capturas de cada paso: ingreso de datos, variables, tabla y gráfico"]},{"id":"q3","p":"3. Tendencia central: media, mediana y moda de las horas; media sin la OT-1220 y comparación; cuál representa mejor el tiempo típico.","indicador":"Calcula medidas de tendencia central (media, mediana y moda) utilizando datos organizados en tablas o listados numéricos por medio de Infostat y planillas de cálculo.","pistas":["Medidas de resumen → Media y Mediana; la moda la ves en la tabla de frecuencias sin agrupar","Datos → Duplicar tabla → borrar la fila OT-1220 → recalcular la media con 19 datos","Repasa la semana 2: ¿qué medida se ve menos afectada por un valor extremo?","Haz también los cálculos en Excel con fórmulas visibles en cada celda"]},{"id":"q4","p":"4. Posición: Q1, Q2 y Q3 interpretados en horas, decil 9 y percentil 90, comparación del P90 con la meta de 6 h y cuántas OT (y qué %) superan la meta.","indicador":"Determina medidas de posición (cuartiles, deciles y percentiles) a partir de conjuntos de datos y funciones estadísticas en Infostat.","pistas":["Medidas de resumen → Mín, Máx, Q1, Q3 y P(90)","Interpreta así: \"el 25 % de las OT se cerró en X horas o menos\"","El decil 9 y el percentil 90 son el mismo punto de corte","Cuenta los valores mayores a 6 y divídelos por 20"]},{"id":"q5","p":"5. Box plot de la muestra completa, valores atípicos y su OT, box plot por turno (medianas y largo de las cajas) y simetría de la distribución.","indicador":"Representa la distribución de datos mediante box plot modelando a través de Infostat y/o planillas de cálculo.","pistas":["Gráficos → Gráficos de caja → horas en Variables","Para comparar turnos, pon Turno en Variable de clasificación","Los atípicos aparecen como puntos fuera de los bigotes","Simetría: mira si la mediana está al centro de la caja y si un bigote es mucho más largo que el otro"]},{"id":"q6","p":"6. Variabilidad: rango, varianza y desviación de la muestra; desviación y CV por turno; comparación absoluta y relativa; recomendación a la jefatura.","indicador":"Relaciona la variabilidad de un conjunto de datos interpretando el rango, la varianza y la desviación estándar obtenidos a partir de resultados obtenidos mediante Infostat.","pistas":["Medidas de resumen → Mín, Máx, Var(n-1) y D.E.","Repite segmentando por Turno y marca D.E. y CV","Absoluta = D.E. (en horas). Relativa = CV (en %). Menor CV = más estable","La recomendación debe usar tus resultados y conectarlos con la meta del 90 % en 6 horas"]}],"rubrica":["Identifica población, muestra y tipos de variables","Construye tablas de frecuencia y gráficos en Infostat","Calcula media, mediana y moda en Infostat y planilla","Determina cuartiles, deciles y percentiles","Representa la distribución con box plot","Interpreta rango, varianza y desviación estándar"],"checklist":["Responder en la plantilla oficial (plantilla_estudiante_aula40.docx, en tu carpeta TAREA S3)","Adjuntar el Excel con las fórmulas visibles en cada celda","Pegar las capturas de cada proceso en Infostat","Declarar al final qué IA usaste y para qué (o que no usaste)","Referencias en formato APA al final","Guardar como PDF: Nombre_Apellido_Tarea1.pdf","Subir en el aula antes del lunes 23 a las 23:59"]}]}]},{"id":"SALPX1203-S1","codigo":"SALPX1203","curso":"Salud Laboral y Primeros Auxilios","semana":1,"titulo":"Anatomía, fisiología y primeros auxilios","desde":"2026-11-03","hasta":"2026-11-09","entregas":[],"misiones":[{"id":"inicio","estacion":"Inicio","titulo":"Derrumbe en la zanja","minutos":3,"intro":"Un caso donde lo que faltó fue preparación.","pasos":[{"t":"lectura","titulo":"El caso","texto":["Dos trabajadores instalan un pilar en una zanja de 3 metros. Las paredes se desprenden y hay un derrumbe.","Uno recibe un golpe en la cabeza con el pilar. El otro sufre una herida cortante profunda en el brazo derecho.","Nadie supo contener la hemorragia y el trabajador se desmayó. No había botiquín y al del golpe en la cabeza nadie lo inmovilizó. Los dos empeoraron hasta que llegó la ambulancia."]},{"t":"mc","id":"s1-i1","p":"El golpe en la cabeza puede comprometer el cráneo y el encéfalo. ¿Qué funciones vitales quedan en riesgo?","ops":["Solo la vista","Conciencia, respiración y circulación","Solo el movimiento del brazo","Ninguna, si no sangra"],"ok":1,"exp":"Además puede haber daño en la columna cervical. Por eso hay que evaluar las funciones vitales e inmovilizar."},{"t":"mc","id":"s1-i2","p":"¿Por qué se desmayó el trabajador de la herida?","ops":["Por el susto","Porque la hemorragia no se controló y bajó su volumen de sangre","Por el calor de la zanja","Por el golpe del compañero"],"ok":1,"exp":"La pérdida continua de sangre produce palidez, sudor, debilidad y desmayo. Controlar la hemorragia a tiempo lo habría evitado."}]},{"id":"cuerpo","estacion":"Anatomía y fisiología","titulo":"Estructura y función","minutos":5,"intro":"Las dos ciencias base para entender cualquier lesión.","pasos":[{"t":"tarjetas","cartas":[["Anatomía","Estudia la estructura del cuerpo: forma y organización. Viene del griego anatomé, disección."],["Fisiología","Estudia cómo funciona el cuerpo. Del griego physis (naturaleza) y logos (estudio)."],["La clave","La estructura permite la función y la función depende de la estructura."],["Anatomía regional, sistémica y clínica","Regional: por zonas (cabeza, tronco). Sistémica: por sistemas. Clínica: relaciona estructura con lesiones y enfermedades."],["Plano sagital","Vertical. Divide el cuerpo en mitad izquierda y derecha."],["Plano frontal o coronal","Vertical, a la altura de las orejas. Divide en parte anterior y posterior."],["Plano horizontal o transversal","Divide en parte superior e inferior. Referencia: el ombligo."],["Homeostasis","Autorregulación que mantiene estables las condiciones internas necesarias para vivir."]]},{"t":"mc","id":"s1-c1","p":"¿Cuál describe mejor la diferencia entre anatomía y fisiología?","ops":["La anatomía estudia funciones y la fisiología estructuras","La anatomía estudia la estructura y la fisiología cómo funciona","Ambas estudian solo los órganos","Son la misma ciencia"],"ok":1,"exp":"Anatomía: cómo está formado el cuerpo. Fisiología: cómo funciona."},{"t":"clasificar","id":"s1-c2","p":"¿Qué plano anatómico divide así el cuerpo?","cats":["Sagital","Frontal","Horizontal"],"items":[["Izquierda y derecha",0],["Adelante y atrás",1],["Arriba y abajo",2]],"exp":"Sagital separa los lados, frontal separa delante y detrás, y horizontal separa arriba y abajo."},{"t":"clasificar","id":"s1-c3","p":"¿A qué sistema funcional pertenece cada parte?","cats":["Dirección y control","Alimentación y transporte","Motor"],"items":[["Sistema nervioso",0],["Sistema endocrino",0],["Aparato digestivo",1],["Aparato respiratorio",1],["Sistema osteomuscular",2]],"exp":"Nervioso y endocrino dirigen. Digestivo, cardiocirculatorio y respiratorio transforman y transportan energía. El osteomuscular mueve."}]},{"id":"vitales","estacion":"Funciones vitales","titulo":"Conciencia, respiración, circulación","minutos":5,"intro":"Lo primero que revisas en cualquier accidentado.","pasos":[{"t":"tarjetas","cartas":[["Funciones vitales básicas","Procesos esenciales para mantenerse vivo: conciencia, respiración y circulación."],["Conciencia","Capacidad de responder a estímulos y estar alerta. Depende del sistema nervioso y del oxígeno al cerebro."],["Respiración","Captar oxígeno y eliminar dióxido de carbono."],["Circulación","Transporte de sangre por el corazón y los vasos: lleva oxígeno y nutrientes y regula la temperatura."],["Evaluación primaria","Valoración inicial para comprobar conciencia, respiración y circulación."],["AVDN","Alerta, responde a la Voz, responde al Dolor, No responde."],["Dónde tomar el pulso","Con índice y medio, nunca con el pulgar. Carótida (cuello) o radial (muñeca)."]]},{"t":"orden","id":"s1-v1","p":"Ordena la escala AVDN de mejor a peor nivel de conciencia.","items":["A: alerta, consciente","V: responde cuando le hablas","D: responde solo a un estímulo de dolor","N: no responde a nada"],"exp":"Mientras más abajo en la escala, más urgente es la atención."},{"t":"mc","id":"s1-v2","p":"Verdadero o falso: la evaluación primaria parte revisando las lesiones menores antes de ver si la persona respira.","ops":["Verdadero","Falso"],"ok":1,"exp":"Falso. Primero se comprueban las funciones vitales: conciencia, respiración y circulación."},{"t":"mc","id":"s1-v3","p":"Una persona no responde a ningún estímulo, no respira y no tiene pulso. ¿Qué corresponde?","ops":["Esperar a ver si despierta","Darle agua","Pedir ayuda y aplicar RCP si estás preparado","Ponerla de lado y dejarla sola"],"ok":2,"exp":"Sin respiración ni pulso se aplica RCP (reanimación cardiopulmonar) y se usa un desfibrilador (DEA) si hay uno cerca."},{"t":"lectura","titulo":"Dato extra: números de emergencia en Chile","texto":["131: SAMU (ambulancia). 132: Bomberos. 133: Carabineros.","Al llamar, di qué pasó, dónde (en tu caso: Estación Puerto Montt y el andén o sector), cuántas personas están afectadas y cómo están. No cortes hasta que te lo indiquen."]}]},{"id":"conceptos","estacion":"Seguridad laboral","titulo":"Peligro, riesgo y compañía","minutos":6,"intro":"Los conceptos que vas a usar en todo el ramo.","pasos":[{"t":"tarjetas","cartas":[["Peligro","Fuente, situación o acto con potencial de causar daño."],["Riesgo","Probabilidad de que el peligro se materialice, junto con la gravedad del daño."],["Accidente del trabajo","Suceso repentino a causa o con ocasión del trabajo que produce lesión, incapacidad o muerte."],["Enfermedad profesional","Causada directamente por el trabajo o por exposición prolongada a agentes del trabajo."],["Emergencia","Situación imprevista que pone en riesgo la vida o la salud y exige intervención inmediata."],["Urgencia","Problema de salud repentino sin riesgo vital. Ej.: un esguince."],["Primeros auxilios","Atención inmediata, temporal y básica en el lugar, hasta que llega ayuda especializada."],["Causas directas","Acciones inseguras (no usar EPP) o condiciones inseguras (escape de gas)."],["Causas básicas","Factores personales (no saber, no poder, no querer) y del trabajo (mala supervisión, sobrecarga)."]]},{"t":"mc","id":"s1-k1","p":"Pedro levanta cajas de 25 kg sin técnica. ¿Cuál es el peligro y cuál el riesgo?","ops":["Peligro: lesionarse la espalda. Riesgo: levantar sin técnica","Peligro: levantar sin técnica. Riesgo: sufrir una lesión musculoesquelética","Los dos son lo mismo","No hay peligro porque 25 kg es el máximo legal"],"ok":1,"exp":"El peligro es lo que puede causar daño (la acción). El riesgo es la probabilidad y gravedad del daño (la lesión)."},{"t":"clasificar","id":"s1-k2","p":"¿Qué tipo de factor de riesgo es cada uno?","cats":["Seguridad","Físico","Químico","Biológico","Ergonómico","Psicosocial"],"items":[["Cable eléctrico en mal estado",0],["Ruido de los trenes",1],["Gases de escape diésel",2],["Virus en contacto con público",3],["Estar de pie todo el turno",4],["Turnos de noche y conflictos con usuarios",5]],"exp":"Todos están presentes en una estación de trenes. Identificarlos es la base de la prevención."},{"t":"clasificar","id":"s1-k3","p":"¿Emergencia o urgencia?","cats":["Emergencia","Urgencia"],"items":[["Paro cardiorrespiratorio",0],["Esguince de tobillo",1],["Hemorragia abundante",0],["Luxación de un dedo",1]],"exp":"En la emergencia la vida está en riesgo. En la urgencia no, pero igual necesita atención en un tiempo razonable."},{"t":"mc","id":"s1-k4","p":"Un guardia no usa guantes al recoger un vidrio y se corta. ¿Qué tipo de causa es?","ops":["Causa directa: acción insegura","Causa básica: factor del trabajo","Condición insegura","No hay causa"],"ok":0,"exp":"No usar EPP es una acción insegura, o sea una causa directa. Si no le habían entregado guantes, la causa básica sería un factor del trabajo."},{"t":"lectura","titulo":"Cómo está Chile","texto":["Según la SUSESO (2025), la tasa de accidentabilidad ronda el 3,5 % y viene bajando.","En enfermedades profesionales crecen los trastornos de salud mental. Los musculoesqueléticos siguen siendo frecuentes, y los auditivos, dermatológicos y respiratorios se mantienen o bajan."],"fuente":"Superintendencia de Seguridad Social (SUSESO), informe anual 2025, citado en el material del curso."}]},{"id":"protocolo","estacion":"Protocolo","titulo":"PAS y los procedimientos generales","minutos":6,"intro":"Cómo llegar a un accidente sin convertirte en la segunda víctima.","pasos":[{"t":"orden","id":"s1-p1","p":"Ordena la técnica PAS.","items":["Proteger: revisar el entorno y eliminar peligros","Avisar: pedir ayuda y llamar a emergencias","Socorrer: atender según la gravedad hasta que llegue ayuda"],"exp":"P-A-S. Primero tu seguridad y la de la víctima."},{"t":"orden","id":"s1-p2","p":"Un trabajador cae inconsciente tras tocar un cable en mal estado. Ordena tus acciones.","items":["No tocarlo mientras haya corriente","Cortar la energía o separarlo con un material aislante","Dar la alarma y llamar al 131","Revisar conciencia, respiración y pulso","Aplicar RCP si no respira y estás preparado"],"exp":"Si lo tocas con corriente activa, te electrocutas tú también. Eso es la P de PAS."},{"t":"mc","id":"s1-p3","p":"Un accidentado te pide agua. ¿Qué haces?","ops":["Le das agua porque la pide","No le das líquidos, aunque los pida","Le das algo con azúcar","Le das agua solo si está consciente"],"ok":1,"exp":"No se dan líquidos. Puede necesitar cirugía, y si pierde la conciencia podría ahogarse."},{"t":"mc","id":"s1-p4","p":"Tras una caída fuerte desde altura, ¿cómo tratas a la víctima?","ops":["La sientas para que respire mejor","Como si tuviera lesión cervical: inmovilizar el cuello y moverla lo mínimo","La llevas caminando a un lugar seguro","La pones boca abajo"],"ok":1,"exp":"En trauma severo se asume lesión de columna. Solo se mueve si es absolutamente necesario, y siempre en horizontal."},{"t":"clasificar","id":"s1-p5","p":"¿Se hace o no se hace?","cats":["Se hace","No se hace"],"items":[["Mantener la temperatura corporal",0],["Dejarlo solo para ir a buscar ayuda si hay otra persona que puede ir",1],["Girarlo de lado si vomita",0],["Acompañarlo todo el tiempo",0],["Moverlo apurado sin necesidad",1]],"exp":"Nunca abandonar al accidentado: si hay otra persona, que ella vaya por ayuda. Se gira de lado si vomita, para despejar la vía aérea."}]},{"id":"botiquin","estacion":"Recursos","titulo":"Botiquín, DEA y la ley","minutos":4,"intro":"Lo que la empresa debe tener listo antes del accidente.","pasos":[{"t":"tarjetas","cartas":[["Código del Trabajo, art. 184","El empleador debe proteger eficazmente la vida y salud de los trabajadores y garantizar atención oportuna."],["Botiquín","Disponible, señalizado, accesible y revisado. Guantes, mascarilla, vendas, gasas, suero fisiológico y termómetro."],["Medicamentos en el botiquín","No deben ir. El botiquín de primeros auxilios no lleva medicamentos."],["Ley 21.156","Exige desfibriladores (DEA) en lugares y espacios de acceso público."],["DEA","Desfibrilador externo automático. Ayuda a restablecer el ritmo del corazón en un paro cardiorrespiratorio."],["Quien presta auxilio","Mantiene la calma, transmite seguridad, organiza, decide con firmeza y tiene conocimientos actualizados."]]},{"t":"mc","id":"s1-b1","p":"¿Cuál de estos elementos NO debe estar en un botiquín de primeros auxilios?","ops":["Guantes quirúrgicos","Suero fisiológico","Analgésicos","Gasas estériles"],"ok":2,"exp":"El botiquín no lleva medicamentos. Quien presta auxilio no debe medicar."},{"t":"mc","id":"s1-b2","p":"Manuel se corta la mano y no hay botiquín. Desde la seguridad laboral, ¿qué es la falta de botiquín?","ops":["Una acción insegura de Manuel","Una condición insegura que aumenta el riesgo de complicaciones","Algo sin importancia","Una causa básica personal"],"ok":1,"exp":"Es una condición insegura del entorno. Además retrasa la evaluación primaria y el control del sangrado."},{"t":"mc","id":"s1-b3","p":"¿Cuál es el primer objetivo de los primeros auxilios?","ops":["Hacer el diagnóstico","Preservar la vida","Dar el alta","Calificar el accidente"],"ok":1,"exp":"Los objetivos son preservar la vida, evitar que se agraven las lesiones, prevenir complicaciones, favorecer la recuperación y mantener a la persona estable hasta que llegue ayuda."}]},{"id":"anden","estacion":"Caso en el andén","titulo":"Un pasajero cae en el andén","minutos":4,"intro":"La semana 1 aplicada a tu turno.","pasos":[{"t":"lectura","titulo":"Situación","texto":["Un tren está llegando. Un pasajero de unos 60 años se desploma en el andén, cerca del borde. Hay gente alrededor sacando fotos."]},{"t":"orden","id":"s1-a1","p":"Ordena tu actuación.","items":["Proteger: alejar a la gente y asegurar que nadie quede cerca del borde mientras entra el tren","Avisar: pedir por radio que avisen al 131 y que traigan el DEA si la estación tiene uno","Evaluar conciencia con AVDN","Revisar respiración y pulso","Si no respira, iniciar RCP hasta que llegue el DEA o el SAMU"],"exp":"PAS más evaluación primaria. Delega tareas concretas: \"tú, llama al 131\" funciona mejor que \"¡que alguien llame!\"."},{"t":"mc","id":"s1-a2","p":"El pasajero responde solo cuando le aprietas el hombro con fuerza. ¿Qué nivel AVDN tiene?","ops":["A","V","D","N"],"ok":2,"exp":"Responde al Dolor. Es un nivel de conciencia alterado y requiere atención urgente."},{"t":"mc","id":"s1-a3","p":"¿Cómo se clasifica este evento?","ops":["Accidente del trabajo tuyo","Emergencia médica de origen común que ocurre en el lugar de trabajo","Enfermedad profesional","Urgencia sin importancia"],"ok":1,"exp":"No lo causó el trabajo, pero ocurre en tu entorno laboral y exige primeros auxilios. Por eso la empresa debe estar preparada."}]}]},{"id":"SALPX1203-S2","codigo":"SALPX1203","curso":"Salud Laboral y Primeros Auxilios","semana":2,"titulo":"Sistema óseo","desde":"2026-11-10","hasta":"2026-11-16","entregas":[{"nombre":"Tarea semana 2 (Unidad 1)","vence":"2026-11-16T23:59:00-03:00","mision":"taller"}],"misiones":[{"id":"inicio","estacion":"Inicio","titulo":"La caída de la escala","minutos":3,"intro":"El caso con que el IACC abre la semana. Léelo y detecta el error.","pasos":[{"t":"lectura","titulo":"El caso","texto":["En una bodega, una trabajadora de 25 años cae desde una escala portátil mientras ordena cajas a 2 metros de altura. Su pie queda atrapado en un peldaño y el tobillo derecho sufre una torsión brusca.","Una compañera la ve en el suelo y le manipula la pierna para «enderezarla», pensando que así le alivia el dolor. El dolor aumenta y la zona se inflama más rápido. En el centro de salud le diagnostican fractura de tobillo."]},{"t":"mc","id":"s2-i1","p":"¿Cuál fue el error de la compañera?","ops":["Avisar demasiado tarde a la ambulancia","Mover y manipular la extremidad lesionada","No aplicar calor en el tobillo","Dejar a la trabajadora acostada en el suelo"],"ok":1,"exp":"Ante una posible fractura no se mueve la extremidad ni se intenta acomodar la lesión. Manipularla agrava el daño, el dolor y la inflamación."},{"t":"mc","id":"s2-i2","p":"Según el material, ¿a qué apuntan primero las acciones ante una lesión del aparato esquelético?","ops":["A diagnosticar el tipo de fractura","A detener el daño a la persona","A completar el registro del accidente","A reubicar el hueso en su lugar"],"ok":1,"exp":"Las acciones primarias buscan, en primer lugar, detener el daño. El diagnóstico lo hace el centro asistencial."}]},{"id":"anatomia","estacion":"Anatomía","titulo":"Los 206 huesos","minutos":6,"intro":"Estructura, funciones y tipos de hueso. Primero tarjetas, después preguntas.","pasos":[{"t":"tarjetas","cartas":[["¿Cuántos huesos tiene el sistema óseo?","206 huesos articulados. Es cerca del 12 % del peso del cuerpo."],["¿Qué lo compone?","Huesos, cartílagos, articulaciones y ligamentos."],["Tendón","Une el músculo al hueso. Huesos y músculos juntos forman el aparato locomotor."],["Ligamento","Banda de tejido resistente que une huesos entre sí y da estabilidad a la articulación."],["Cartílago","Tejido flexible que recubre los extremos de los huesos y evita el roce entre ellos."],["Periostio","Membrana externa del hueso. Lo protege y lleva vasos y nervios (por eso duele tanto al dañarse)."],["Hueso compacto vs. esponjoso","Compacto: capa externa, dura, da fuerza. Esponjoso: interior poroso, liviano, absorbe impactos."],["Médula ósea roja / amarilla","Roja: produce células sanguíneas (hematopoyesis). Amarilla: guarda grasa como reserva de energía."],["7 funciones del hueso","Soporte, protección de órganos, movimiento, homeostasis mineral, reservorio de minerales, producción de células sanguíneas y almacén de grasa."],["Columna vertebral (33 a 34 vértebras)","7 cervicales, 12 dorsales, 5 lumbares, 5 sacras y 4-5 coxígeas (sacras y coxígeas fusionadas)."],["Fémur","Hueso del muslo. El más largo del cuerpo; soporta hasta 1 tonelada de presión vertical."],["Costillas","24 en total, 12 por lado: 7 verdaderas, 3 falsas y 2 flotantes."]]},{"t":"mc","id":"s2-a1","p":"¿Qué estructura une los huesos ENTRE SÍ y estabiliza la articulación?","ops":["Tendón","Cartílago","Ligamento","Periostio"],"ok":2,"exp":"El ligamento une hueso con hueso. El tendón une músculo con hueso."},{"t":"mc","id":"s2-a2","p":"Las vértebras y los huesos de la cara se clasifican como huesos…","ops":["Largos","Cortos","Planos","Irregulares"],"ok":3,"exp":"Irregulares: no calzan en otra categoría. Ejemplos: vértebras y huesos neumáticos de la cara."},{"t":"mc","id":"s2-a3","p":"El húmero, el radio y el cúbito son ejemplos de huesos…","ops":["Largos","Planos","Cortos","Irregulares"],"ok":0,"exp":"Largos: su longitud supera al ancho y grosor. Se distinguen diáfisis, epífisis y metáfisis."},{"t":"mc","id":"s2-a4","p":"¿Qué parte del hueso produce glóbulos rojos, blancos y plaquetas?","ops":["Médula ósea amarilla","Médula ósea roja","Hueso compacto","Cartílago articular"],"ok":1,"exp":"La médula ósea roja hace la hematopoyesis. La amarilla almacena grasa."},{"t":"clasificar","id":"s2-a5","p":"Clasifica cada hueso según su forma.","cats":["Largo","Corto","Plano","Irregular"],"items":[["Fémur",0],["Huesos de la muñeca",1],["Escápula",2],["Vértebra",3],["Costilla",2],["Tibia",0]],"exp":"Largos: fémur y tibia. Cortos: muñeca y retropié. Planos: cráneo, escápula y costillas. Irregulares: vértebras y huesos de la cara."},{"t":"mc","id":"s2-a6","p":"La médula espinal, que va dentro de la columna, ¿a qué sistema pertenece?","ops":["Al sistema óseo","Al sistema nervioso central","Al sistema muscular","Al aparato locomotor"],"ok":1,"exp":"Pertenece al sistema nervioso central. La columna solo la protege dentro del conducto raquídeo."}]},{"id":"lesiones","estacion":"Lesiones","titulo":"Fractura, luxación o esguince","minutos":5,"intro":"Las tres lesiones óseas típicas del trabajo y cómo distinguirlas.","pasos":[{"t":"tarjetas","cartas":[["Fractura","Pérdida de continuidad del hueso por traumatismo directo o indirecto (hueso roto o con fisura)."],["Fractura cerrada vs. abierta","Cerrada: no rompe la piel. Abierta: el hueso rompe la piel de dentro hacia fuera; más riesgo de infección y hemorragia."],["Luxación","Pérdida total o parcial de la relación entre los huesos de una articulación: hueso fuera de su articulación."],["Esguince","Estiramiento excesivo del ligamento por movimiento brusco, caída, golpe o torsión. Grados 1, 2 y 3 (el 3 es el más grave)."],["Causas laborales típicas","Caídas de igual o distinto nivel, golpes, atropellos, atrapamientos, aprisionamientos y sobreesfuerzos."]]},{"t":"clasificar","id":"s2-l1","p":"¿Qué lesión describe cada situación?","cats":["Fractura","Luxación","Esguince"],"items":[["Un guardia se tuerce el tobillo al bajar del andén; hay hinchazón y siente que el pie «le falla».",2],["Tras una caída con el brazo estirado, el hombro queda deformado y no lo puede mover.",1],["Una grúa horquilla golpea a un peatón; el hueso de la pierna asoma por una herida.",0],["Golpe directo en el antebrazo; dolor intenso al presionar y deformidad del hueso.",0],["Un movimiento brusco en la muñeca estira el ligamento más de lo normal.",2]],"exp":"Esguince: daño del ligamento. Luxación: hueso fuera de la articulación. Fractura: hueso roto. Ante la duda entre fractura y luxación, se actúa como si fuera fractura."},{"t":"mc","id":"s2-l2","p":"Un trabajador cae de una estructura metálica, amortigua con el brazo y el hombro queda deformado y muy doloroso. Es una luxación, que se define como…","ops":["Estiramiento excesivo del ligamento","Interrupción de la continuidad de un hueso","Pérdida total o parcial de la relación entre los huesos de la articulación","Estiramiento excesivo de la articulación"],"ok":2,"exp":"Luxación = hueso fuera de su articulación. Es la pregunta del ejercicio oficial de la semana."},{"t":"mc","id":"s2-l3","p":"¿Qué hace más urgente una fractura abierta que una cerrada?","ops":["Duele menos pero se infecta","Hay riesgo de infección y puede haber hemorragia abundante","Siempre compromete la columna","No necesita inmovilización"],"ok":1,"exp":"En la abierta el hueso rompe la piel: herida expuesta, riesgo de infección y posible hemorragia."}]},{"id":"auxilios","estacion":"Primeros auxilios","titulo":"Qué hacer, y qué no","minutos":7,"intro":"Técnicas para cada lesión e inmovilización. Esto es lo que más pesa en la tarea.","pasos":[{"t":"orden","id":"s2-p1","p":"Fractura cerrada en el brazo derecho por accidente del trabajo. Ordena los pasos de primeros auxilios.","items":["Tratar de no mover al accidentado","Examinar visualmente y retirar objetos que impidan la circulación","Comprobar la presencia de pulso en la extremidad","Aplicar frío local (no directamente sobre la piel)","Inmovilizar la extremidad con férulas o tablillas","Trasladar urgente a un centro asistencial"],"exp":"Es el orden del ejercicio oficial de la semana: no mover, examinar, pulso, frío, inmovilizar y trasladar."},{"t":"mc","id":"s2-p2","p":"Fractura abierta: el hueso asoma por la herida. ¿Qué corresponde?","ops":["Reintroducir el hueso con cuidado y vendar","Cubrir con gasa o tela limpia y presión suave alrededor de la herida","Lavar con agua y dejar la herida al aire","Aplicar hielo directo sobre el hueso expuesto"],"ok":1,"exp":"Nunca reintroducir el hueso. Se cubre para evitar infección y se controla el sangrado con presión suave alrededor."},{"t":"mc","id":"s2-p3","p":"No sabes si es luxación o fractura. ¿Qué haces?","ops":["Actúas como si fuera fractura","Intentas reubicar la articulación","Esperas a que baje la hinchazón para decidir","La tratas como esguince"],"ok":0,"exp":"Ante la duda, se actúa como fractura. En una luxación nunca se intenta reubicar la articulación: se inmoviliza tal como está."},{"t":"mc","id":"s2-p4","p":"¿Cuál de estas acciones corresponde SOLO al esguince según el material?","ops":["Elevar la extremidad e inmovilizar la articulación","Reintroducir el hueso","Comprobar pulso carotídeo","Aplicar calor local"],"ok":0,"exp":"Esguince: frío local, elevación e inmovilización, y traslado. La elevación solo se hace si la zona ya está inmovilizada y no causa dolor."},{"t":"clasificar","id":"s2-p5","p":"¿Qué inmovilizador usarías?","cats":["Férula","Cabestrillo","Collarín cervical","Tablero espinal"],"items":[["Sostener el antebrazo en posición cómoda y segura",1],["Pierna con posible fractura, a ambos lados de la extremidad",0],["Sospecha de lesión en el cuello tras una caída",2],["Trasladar a la víctima completa sin moverle la columna",3]],"exp":"Cabestrillo: miembro superior. Férula: extremidades (se puede improvisar con listones). Collarín: zona cervical, del tamaño correcto. Tablero o camilla: inmovilización global (se puede improvisar con una puerta)."},{"t":"mc","id":"s2-p6","p":"Al vendar una férula, ¿qué debes verificar después?","ops":["Que la venda quede lo más apretada posible","La circulación: color, temperatura y sensibilidad de la piel","Que la extremidad quede elevada sobre el corazón","Que el afectado pueda mover los dedos con fuerza"],"ok":1,"exp":"Firme pero cómodo. Hay que revisar la circulación: color, temperatura y sensibilidad."}]},{"id":"normativa","estacion":"Normativa","titulo":"Lo que dice la ley","minutos":5,"intro":"Leyes y decretos que piden en la pregunta 3 de la tarea.","pasos":[{"t":"tarjetas","cartas":[["Ley 16.744","Seguro de accidentes del trabajo y enfermedades profesionales. Es la base de toda la normativa preventiva."],["DS 594","Condiciones sanitarias y ambientales básicas del lugar de trabajo: riesgos físicos (ruido, iluminación, etc.), químicos y biológicos, seguridad general, emergencias y ergonomía."],["DS 44","Identificar y evaluar riesgos, programas de prevención, informar los peligros al personal y capacitar. Ante riesgo grave e inminente: informar y suspender faenas o evacuar."],["Leyes 20.001 y 20.949","Carga manual máxima: 25 kg hombres; 20 kg mujeres y menores de 18. Prohibida para embarazadas."],["Art. 76 Ley 16.744","Accidente grave o fatal: suspender de inmediato las faenas afectadas (y evacuar si es necesario) e informar a la Inspección del Trabajo y a la SEREMI de Salud."],["Art. 184 Código del Trabajo","El empleador debe proteger eficazmente la vida y salud de los trabajadores y garantizar atención oportuna ante accidentes."]]},{"t":"clasificar","id":"s2-n1","p":"¿Qué norma regula cada cosa?","cats":["DS 594","DS 44","Ley 20.001 / 20.949","Art. 76 Ley 16.744"],"items":[["Peso máximo de carga manual",2],["Iluminación, ruido y condiciones del lugar de trabajo",0],["Informar a la Inspección del Trabajo y a la SEREMI tras un accidente grave",3],["Identificar y evaluar los riesgos y capacitar al personal",1],["Suspender faenas ante un accidente fatal",3]],"exp":"DS 594: condiciones del lugar. DS 44: gestión de riesgos, información y capacitación. 20.001/20.949: carga manual. Art. 76: accidente grave o fatal."},{"t":"mc","id":"s2-n2","p":"¿Cuántos kilos puede levantar como máximo una trabajadora de 30 años, según la normativa?","ops":["25 kg","20 kg","15 kg","No hay límite"],"ok":1,"exp":"20 kg para mujeres y menores de 18 años; 25 kg para hombres. Las embarazadas no pueden cargar manualmente."},{"t":"mc","id":"s2-n3","p":"Ocurre un accidente grave en una bodega. ¿Qué debe hacer el empleador de inmediato?","ops":["Esperar el informe de la mutualidad","Suspender las faenas afectadas e informar a la Inspección del Trabajo y a la SEREMI de Salud","Solo registrarlo en el libro de accidentes","Despedir al operador responsable"],"ok":1,"exp":"Art. 76 de la Ley 16.744 (incisos cuarto y quinto)."}]},{"id":"anden","estacion":"Caso en el andén","titulo":"Turno en la estación","minutos":5,"intro":"Un caso de tu propio trabajo. Combina lo de la semana 1 (PAS y signos vitales) con lo de esta semana.","pasos":[{"t":"lectura","titulo":"Situación","texto":["Son las 7:40 en la estación. Un trabajador de mantención baja por una escala portátil junto a la vía, pisa un peldaño mojado y cae cerca de 1,5 m. Queda en el suelo, consciente, sujetándose la pierna. Tiene el muslo deformado y no puede moverla. Por la vía cercana todavía circulan equipos.","Eres el guardia más cercano."]},{"t":"mc","id":"s2-c1","p":"Llegas al lugar. ¿Qué es lo primero según la técnica PAS?","ops":["Socorrer: revisar la pierna","Proteger: evaluar el entorno y asegurar que no haya peligro para ti ni para él","Avisar: llamar a la ambulancia antes de acercarte","Moverlo de inmediato al andén"],"ok":1,"exp":"P-A-S: Proteger, Avisar, Socorrer. Primero el entorno (aquí, los equipos en la vía). Después avisar y recién ahí socorrer."},{"t":"orden","id":"s2-c2","p":"Ordena la técnica PAS.","items":["Proteger: evaluar el entorno y los peligros","Avisar: activar la alarma o pedir ayuda por radio","Socorrer: reconocer y priorizar las lesiones"],"exp":"Proteger, avisar y socorrer. Avisar puede ser pedir a otra persona que llame mientras tú atiendes."},{"t":"mc","id":"s2-c3","p":"El trabajador te responde cuando le hablas, pero está confundido. En la escala AVDN, ¿dónde está?","ops":["A: alerta","V: responde a la voz","D: responde solo al dolor","N: sin respuesta"],"ok":1,"exp":"AVDN mide la conciencia: Alerta, Voz, Dolor y No responde."},{"t":"mc","id":"s2-c4","p":"Muslo deformado tras la caída. ¿Qué hueso probablemente se fracturó y qué haces?","ops":["Tibia; le pides que intente pararse","Fémur; no lo mueves, frío envuelto, inmovilizas con férulas y traslado urgente","Rótula; elevas la pierna de inmediato","Peroné; le das agua y esperas"],"ok":1,"exp":"El muslo es el fémur. Además fue una caída de altura (trauma), así que hay que tratarlo como posible lesión cervical y no darle líquidos."},{"t":"mc","id":"s2-c5","p":"Notas la piel fría y húmeda, náuseas y la mirada sin brillo. ¿Qué indica y qué haces?","ops":["Hipotermia; lo abrigas y le das café","Posible shock; lo mantienes horizontal, abrigado y lo acompañas","Desmayo leve; lo sientas","Nada importante; sigues con la férula"],"ok":1,"exp":"Son signos de shock. Lo indicado: posición horizontal, mantener la temperatura y no abandonarlo nunca. Elevar los pies a 45° no corresponde aquí porque tiene una pierna fracturada."},{"t":"mc","id":"s2-c6","p":"¿Qué falla de seguridad del lugar facilitó este accidente, y qué norma la cubre?","ops":["Peldaño mojado y equipos circulando: condiciones del lugar (DS 594) y evaluación de riesgos (DS 44)","Ninguna, fue mala suerte","Solo la falta de casco","El guardia llegó tarde"],"ok":0,"exp":"Superficie resbaladiza y tránsito de equipos son condiciones inseguras. Encontrar este tipo de causas es justamente lo que pide la tarea."}]},{"id":"taller","estacion":"Taller de la tarea","titulo":"Tarea semana 2","minutos":20,"intro":"Caso de la grúa horquilla. Anota tus ideas por pregunta y pide retroalimentación según la rúbrica antes de escribir la versión final en la plantilla.","pasos":[{"t":"taller","caso":"En una bodega, una grúa horquilla retrocede de forma repentina y atropella a un trabajador que cruzaba por una zona no habilitada para peatones. Resultado: fractura grave en la pierna derecha, entre la cadera y la rodilla. No había delimitación ni señalización de vías peatonales, el operador no tomó precauciones, había alto nivel de ruido y circulación de maquinaria, y el piso estaba mojado por una filtración de aguas lluvias.","preguntas":[{"id":"q1","p":"1. Describe las condiciones del entorno y los riesgos presentes al momento del accidente. ¿Qué procedimientos de primeros auxilios se deberían haber seguido?","indicador":"Describe los protocolos generales de primeros auxilios considerando los riesgos del entorno laboral.","pistas":["Haz la lista de riesgos del caso: maquinaria en movimiento, ruido, piso mojado, sin señalización","PAS: ¿cómo proteges a la víctima si hay grúas circulando?","Signos vitales: conciencia (AVDN), respiración, circulación","Shock, no dar líquidos, no abandonar y traslado en posición horizontal"]},{"id":"q2","p":"2. Según el tipo de lesión y la parte afectada, explica las técnicas de primeros auxilios a seguir según anatomía y fisiología humana.","indicador":"Determina las técnicas de primeros auxilios según estructura, funcionamiento y tipo de lesiones del sistema óseo.","pistas":["Entre cadera y rodilla está el fémur: hueso largo, el más resistente y largo del cuerpo","¿Fractura abierta o cerrada? Explica qué harías en cada caso","Pasos: no mover, examinar, pulso, frío envuelto, inmovilizar con férulas y traslado","Relaciona la función del hueso (soporte y movimiento) con por qué se inmoviliza"]},{"id":"q3","p":"3. ¿Qué obligaciones legales y normativas debió implementar la empresa? Fundamenta.","indicador":"Verifica el cumplimiento legal y normativo frente a la ocurrencia de lesiones o patologías de tipo ósea.","pistas":["Ley 16.744 y el art. 184 del Código del Trabajo como base","DS 594: condiciones del lugar (piso, ruido, tránsito)","DS 44: identificar riesgos, informar y capacitar (operador y peatones)","Art. 76: fractura grave → suspender faenas e informar a la Inspección del Trabajo y a la SEREMI"]}],"rubrica":["Reconoce anatomía, fisiología y tipos de lesiones de origen laboral","Describe protocolos generales de primeros auxilios según los riesgos del entorno","Determina técnicas de primeros auxilios según el sistema óseo","Verifica el cumplimiento legal y normativo","Usa términos de la disciplina con pertinencia"],"checklist":["Responder en la plantilla oficial (plantilla_estudiante_aula40.docx, está en tu carpeta TAREA S2)","Respuestas de elaboración propia","Referencias en formato APA al final","Guardar como PDF: Nombre_Apellido_Tarea1.pdf","Subir en el aula antes del lunes 16 a las 23:59"]}]}]},{"id":"SALPX1203-S3","codigo":"SALPX1203","curso":"Salud Laboral y Primeros Auxilios","semana":3,"titulo":"Sistema osteomuscular","desde":"2026-11-17","hasta":"2026-11-23","entregas":[],"misiones":[{"id":"inicio","estacion":"Inicio","titulo":"La muñeca de la temporera","minutos":3,"intro":"El caso con que parte la semana: una lesión que no vino de un golpe.","pasos":[{"t":"lectura","titulo":"El caso","texto":["En un packing frutícola, una trabajadora lleva una semana seleccionando manzanas y abasteciendo la máquina de envasado. Trabaja 8 horas, tiene 45 minutos de colación y la empresa no tiene pausas saludables.","Al final de la jornada tiene dolor e inflamación en la muñeca derecha y no puede seguir trabajando. Hay que trasladarla a atención médica.","La semana pasada viste los huesos, que dan estructura. Esta semana toca el sistema muscular, que genera el movimiento: los músculos tiran de los huesos a través de los tendones."]},{"t":"mc","id":"s3-i1","p":"¿Qué factor de riesgo explica mejor la lesión de la trabajadora?","ops":["Un golpe contra la máquina","Movimientos repetitivos sin pausas","Exposición a ruido","Trabajar de noche"],"ok":1,"exp":"Es sobreesfuerzo por una tarea repetitiva. El material lo asocia a una probable tendinitis de muñeca."},{"t":"mc","id":"s3-i2","p":"¿Qué estructuras están comprometidas con más probabilidad?","ops":["El fémur y la rodilla","Los músculos del antebrazo y los tendones de la muñeca","El diafragma","Las vértebras cervicales"],"ok":1,"exp":"Músculos del antebrazo y muñeca, los tendones que los unen a los huesos de la mano y, cerca, ligamentos y la articulación de la muñeca."}]},{"id":"musculos","estacion":"Anatomía","titulo":"Los motores del cuerpo","minutos":6,"intro":"De qué está hecho un músculo y cómo se clasifican.","pasos":[{"t":"tarjetas","cartas":[["Sistema osteomuscular","Huesos, músculos, articulaciones, tendones y ligamentos. Mueve el cuerpo, mantiene la postura y protege órganos."],["¿Cuántos músculos?","Aproximadamente 650, unidos a los huesos por tendones."],["Fibra muscular","Célula alargada con capacidad de contraerse."],["Tendón","Estructura fuerte que une el músculo al hueso y transmite el movimiento."],["Nervios y vasos","Los nervios llevan la orden del cerebro para contraer o relajar. Los vasos llevan oxígeno y nutrientes."],["Músculo liso","Involuntario. Paredes del estómago, intestino, esófago, arterias y venas."],["Músculo estriado","Potente y rápido, casi siempre voluntario. Forma el aparato locomotor."],["Músculo cardíaco","Estriado, pero involuntario. Es el miocardio: sus fibras se contraen sincronizadas."],["Según su forma","Largos (extremidades), cortos (columna), planos (abdomen) y circulares u orbiculares (ojos, boca)."]]},{"t":"clasificar","id":"s3-m1","p":"¿Qué tipo de tejido muscular es cada uno?","cats":["Liso","Estriado","Cardíaco"],"items":[["Pared del estómago",0],["Bíceps",1],["Miocardio",2],["Paredes de las arterias",0],["Cuádriceps",1],["Intestino",0]],"exp":"Liso: órganos y vasos, involuntario. Estriado: aparato locomotor, voluntario. Cardíaco: el corazón, estriado pero involuntario."},{"t":"clasificar","id":"s3-m2","p":"Clasifica según la forma del músculo.","cats":["Largo","Corto","Plano","Circular"],"items":[["Músculos de los brazos y piernas",0],["Músculos de la columna vertebral",1],["Músculos del abdomen",2],["Orbicular de los párpados",3],["Orbicular de los labios",3]],"exp":"Largos en extremidades, cortos en la columna, planos en el abdomen y circulares (orbiculares) para abrir y cerrar ojos o boca."},{"t":"mc","id":"s3-m3","p":"¿Qué función NO cumple el sistema muscular?","ops":["Producir calor","Mantener la postura","Fabricar glóbulos rojos","Ayudar a la circulación al contraerse"],"ok":2,"exp":"Los glóbulos rojos se fabrican en la médula ósea roja (lo viste la semana pasada). El músculo produce calor, da postura, forma y ayuda a la circulación."},{"t":"mc","id":"s3-m4","p":"Cuando hace mucho frío y tiritas, ¿qué está pasando?","ops":["Los músculos se relajan para ahorrar energía","Contracciones rápidas e involuntarias que aceleran el metabolismo y generan calor","Falla del sistema nervioso","Es un calambre por falta de sales"],"ok":1,"exp":"Tiritar es una contracción involuntaria cuyo objetivo es subir la temperatura corporal."},{"t":"mc","id":"s3-m5","p":"Músculos que están bajo la piel y producen movimientos visibles. ¿Cómo se llaman según su ubicación?","ops":["Profundos","Viscerales","Superficiales","Orbiculares"],"ok":2,"exp":"Superficiales: bajo la piel. Profundos: debajo de ellos, para estabilidad. Viscerales: en los órganos internos."}]},{"id":"mapa","estacion":"Mapa del cuerpo","titulo":"¿Quién mueve qué?","minutos":5,"intro":"Los músculos clave por zona. Ojo con las parejas que trabajan al revés.","pasos":[{"t":"tarjetas","cartas":[["Masetero","Músculo masticador. Cierra la mandíbula y ayuda a soplar junto con el temporal."],["Diafragma","Separa tórax y abdomen. Protagonista de la respiración."],["Trapecio","Sostiene la cabeza y mueve hombros y cuello."],["Deltoides","Recubre el hombro. Levanta y desplaza el brazo."],["Manguito rotador","Cuatro músculos que dan estabilidad al hombro."],["Bíceps y tríceps","Antagonistas: el bíceps flexiona el brazo y el tríceps lo extiende."],["Glúteos","Extienden y rotan la cadera. Mantienen el tronco erguido para caminar."],["Gemelos y sóleo","Flexión y extensión del pie al caminar. Se insertan en el calcáneo por el tendón de Aquiles."],["Músculos profundos de la espalda","Cerca de la columna: postura, espalda recta, movimientos finos y protección de la médula."]]},{"t":"clasificar","id":"s3-z1","p":"¿En qué zona está cada músculo?","cats":["Cabeza y cuello","Tórax y espalda","Extremidad superior","Extremidad inferior"],"items":[["Masetero",0],["Serratos",1],["Deltoides",2],["Cuádriceps",3],["Dorsal ancho",1],["Supinadores y pronadores",2],["Gemelos",3]],"exp":"Serratos y dorsal ancho van en tórax y espalda. Supinadores y pronadores giran el antebrazo. Cuádriceps y gemelos son de la pierna."},{"t":"mc","id":"s3-z2","p":"Para levantar una caja doblas el codo. ¿Qué músculo hace la flexión?","ops":["Tríceps","Bíceps","Deltoides","Trapecio"],"ok":1,"exp":"El bíceps flexiona y el tríceps extiende. Por eso se dice que son antagonistas."},{"t":"mc","id":"s3-z3","p":"¿Qué tendón conecta los gemelos con el calcáneo?","ops":["Tendón rotuliano","Tendón de Aquiles","Manguito rotador","Epicóndilo"],"ok":1,"exp":"El tendón de Aquiles permite mover el pie y parte de la pierna."},{"t":"mc","id":"s3-z4","p":"Luis levantó una caja pesada con la espalda inclinada y sin doblar las rodillas. ¿Qué músculos debieron hacer la mayor parte de la fuerza?","ops":["Los de la espalda baja","Los de las piernas (cuádriceps y glúteos), con la espalda recta","Los del cuello","Los del antebrazo"],"ok":1,"exp":"Al doblar rodillas y mantener la espalda recta, la carga la llevan los músculos grandes de las piernas. Así se protege la zona lumbar, donde Luis sintió el dolor."}]},{"id":"lesiones","estacion":"Lesiones","titulo":"Cuando el trabajo pasa la cuenta","minutos":6,"intro":"Las lesiones y patologías musculares más comunes en el trabajo.","pasos":[{"t":"tarjetas","cartas":[["Contractura","Contracción involuntaria, permanente y dolorosa. Suele venir de sobreesfuerzo o agotamiento."],["Calambre","Espasmo involuntario, NO permanente. Sobreesfuerzo con pérdida de sales minerales."],["Rotura fibrilar","Rotura de fibras por contracción violenta, estiramiento brusco, agotamiento, deshidratación o golpe."],["Tendinitis","Inflamación del tendón por posturas forzadas o movimientos repetitivos."],["Túnel carpiano","Compresión del nervio mediano en la muñeca. Adormecimiento, dolor y pérdida de fuerza."],["Epicondilitis","\"Codo de tenista\". Microlesiones en los tendones del epicóndilo por extender la muñeca y girar el antebrazo una y otra vez."],["Lumbago","Dolor en la zona baja de la espalda. Puede ser mecánico o neurogénico (ciática), agudo o crónico."],["Ergonomía","Disciplina que previene estas lesiones adaptando puestos, equipos y métodos a las personas."]]},{"t":"clasificar","id":"s3-l1","p":"¿Qué lesión describe cada situación?","cats":["Tendinitis","Túnel carpiano","Epicondilitis","Lumbago"],"items":[["Digitadora con hormigueo y adormecimiento en los dedos",1],["Dolor agudo en la espalda baja al levantar un saco",3],["Dolor en el codo de un trabajador que atornilla todo el día",2],["Tendón de la muñeca inflamado tras una semana seleccionando fruta",0]],"exp":"Hormigueo y adormecimiento indican el nervio mediano (túnel carpiano). El codo es epicondilitis. La espalda baja es lumbago. Un tendón inflamado es tendinitis."},{"t":"mc","id":"s3-l2","p":"¿Cuál es la diferencia entre contractura y calambre?","ops":["No hay diferencia","La contractura es permanente y el calambre no","El calambre siempre requiere cirugía","La contractura es voluntaria"],"ok":1,"exp":"Los dos son involuntarios. La contractura se mantiene; el calambre es un espasmo que pasa."},{"t":"mc","id":"s3-l3","p":"Según SUSESO, una tendinitis que aparece tras meses de exposición a movimientos repetitivos y con historia ocupacional que la respalda, ¿cómo podría calificarse?","ops":["Accidente del trabajo","Enfermedad profesional","Accidente de trayecto","Enfermedad común, siempre"],"ok":1,"exp":"Si hay exposición previa suficiente a un agente de riesgo, puede ser enfermedad profesional. Si es un evento puntual de sobrecarga, es accidente del trabajo."},{"t":"mc","id":"s3-l4","p":"Un trabajador siente un tirón en la espalda en el momento exacto en que levanta una carga. ¿Cómo lo trata el Compendio de SUSESO?","ops":["Patología por exposición a agentes de riesgo","Patología producto de un accidente del trabajo: evento puntual de sobrecarga biomecánica","No se cubre","Enfermedad profesional automática"],"ok":1,"exp":"Lo agudo y puntual se trata como accidente. Igual se necesita evaluación médica y estudio del puesto para calificarlo."}]},{"id":"auxilios","estacion":"Primeros auxilios","titulo":"RICE: reposo, hielo, compresión, elevación","minutos":6,"intro":"La técnica base para lesiones de músculos, huesos, ligamentos y articulaciones.","pasos":[{"t":"lectura","titulo":"El objetivo","texto":["Proteger la zona, reducir el dolor y evitar que la lesión empeore hasta que llegue atención especializada.","RICE viene del inglés: Rest (reposo), Ice (hielo), Compression (compresión) y Elevation (elevación). Después de aplicarla, siempre hay que derivar a un centro asistencial."]},{"t":"orden","id":"s3-p1","p":"Ordena las letras de RICE.","items":["Reposo: dejar de usar la zona e inmovilizarla","Hielo: frío envuelto, máximo 20 minutos","Compresión: venda elástica ajustada sin cortar la circulación","Elevación: sobre el nivel del corazón si se puede"],"exp":"R-I-C-E. Y al final, derivar a evaluación profesional."},{"t":"mc","id":"s3-p2","p":"Verdadero o falso: el hielo se aplica directo sobre la piel y de forma permanente.","ops":["Verdadero","Falso"],"ok":1,"exp":"Falso. Se pone en una bolsa, envuelto en una toalla o paño, por no más de 20 minutos seguidos, cada 2 a 3 horas."},{"t":"mc","id":"s3-p3","p":"Al vendar con compresión, ¿cómo sabes que quedó demasiado apretado?","ops":["Si la persona dice que está firme","Si los dedos se ponen fríos, pálidos o con hormigueo","Si la venda es elástica","Nunca queda demasiado apretado"],"ok":1,"exp":"El vendaje debe ajustar pero no cortar la circulación. Dedos fríos, pálidos, morados o con hormigueo indican que hay que soltarlo."},{"t":"mc","id":"s3-p4","p":"Sospechas una fractura o luxación. ¿Qué haces?","ops":["Intentas acomodar el hueso","Inmovilizas en la posición en que está, incluyendo la articulación de arriba y la de abajo","Pides que camine para probar","Masajeas la zona"],"ok":1,"exp":"Nunca reubicar el hueso. Se inmoviliza como está (férula, tabla o algo improvisado), abarcando las articulaciones vecinas."},{"t":"mc","id":"s3-p5","p":"¿Para qué sirve elevar la extremidad?","ops":["Para que no llegue más sangre a la zona y no aumente la inflamación","Para que la persona se distraiga","Para enfriar la zona","Para estirar el músculo"],"ok":0,"exp":"Elevar sobre el nivel del corazón disminuye la acumulación de sangre y la inflamación."},{"t":"lectura","titulo":"Dato extra: RICE tiene variantes","texto":["En guías de medicina deportiva vas a encontrar PRICE, que agrega la P de Protección: cuidar la zona de un nuevo golpe. Otras guías más recientes, como POLICE o PEACE & LOVE, cambian el reposo total por una carga gradual y protegida en los días siguientes, indicada por un profesional.","En la evaluación de este ramo usa RICE, que es la técnica del material. Las variantes muestran que el primer paso es el mismo en todas: detener la actividad y proteger la zona."],"fuente":"Bleakley et al., British Journal of Sports Medicine (2012); Dubois y Esculier, BJSM (2020)."}]},{"id":"normativa","estacion":"Normativa","titulo":"Lo que exige la ley","minutos":5,"intro":"Las normas chilenas que regulan los trastornos musculoesqueléticos.","pasos":[{"t":"tarjetas","cartas":[["Ley 16.744","Seguro de accidentes del trabajo y enfermedades profesionales. Obliga a identificar peligros y evaluar riesgos."],["D.S. 109 (1968)","Califica accidentes y enfermedades profesionales. Las lesiones musculares pueden caber en ambos."],["D.S. 594, art. 110 a)","Obliga a evaluar los factores de riesgo de trastornos musculoesqueléticos de extremidades superiores."],["Protocolo TMERT","Metodología para identificar y evaluar riesgos de trastornos musculoesqueléticos. Incluye vigilancia de la salud."],["Riesgos que mira el TMERT","Movimientos repetitivos, posturas forzadas, manipulación de cargas o personas y vibraciones."],["Ley 20.001","Regula el manejo manual de carga."],["Ley 20.949 (2016)","Bajó el máximo a 25 kg. 20 kg para menores de 18 y mujeres. Prohibido para embarazadas. Prioriza medios mecánicos."]]},{"t":"mc","id":"s3-n1","p":"¿Cuál es el peso máximo de carga manual para un trabajador adulto según la Ley 20.949?","ops":["50 kg","25 kg","20 kg","No hay límite"],"ok":1,"exp":"25 kg. Antes eran 50 kg. Para menores de 18 años y mujeres el límite es 20 kg."},{"t":"mc","id":"s3-n2","p":"Una trabajadora embarazada en la bodega de la estación, ¿cuántos kilos puede cargar manualmente?","ops":["20 kg","25 kg","10 kg","Ninguno: la ley lo prohíbe"],"ok":3,"exp":"La Ley 20.949 prohíbe a las embarazadas las operaciones de carga y descarga manual."},{"t":"clasificar","id":"s3-n3","p":"¿Qué norma corresponde a cada exigencia?","cats":["D.S. 594","Protocolo TMERT","Ley 20.949"],"items":[["Evaluar riesgos de extremidades superiores (art. 110 a)",0],["Metodología de evaluación y vigilancia de la salud",1],["Límite de 25 kg",2],["Priorizar medios mecánicos para mover cargas",2]],"exp":"El D.S. 594 pone la obligación, el TMERT da el método y la Ley 20.949 fija los pesos."},{"t":"mc","id":"s3-n4","p":"¿Qué medida preventiva ayudaría más a la trabajadora del packing?","ops":["Darle un analgésico al empezar el turno","Pausas, rotación de tareas y evaluación del puesto con el TMERT","Que trabaje más rápido para terminar antes","Cambiarla al turno de noche"],"ok":1,"exp":"La ergonomía ataca la causa: pausas, rotación y diseño del puesto. El analgésico solo tapa el síntoma."}]},{"id":"anden","estacion":"Caso en el andén","titulo":"Tres situaciones en tu turno","minutos":6,"intro":"Lo de la semana aplicado a la estación de Puerto Montt.","pasos":[{"t":"lectura","titulo":"Situación 1","texto":["Una pasajera baja apurada las escaleras del andén, pisa mal y se tuerce el tobillo. Puede apoyar un poco el pie, pero está hinchándose."]},{"t":"orden","id":"s3-c1","p":"Ordena lo que haces.","items":["Verificar que la zona sea segura y alejar a la pasajera del flujo de gente","Sentarla y pedirle que no apoye el pie","Aplicar frío envuelto en un paño, máximo 20 minutos","Vendar con compresión sin cortar la circulación y elevar el pie","Recomendar evaluación médica y dejar registro del incidente"],"exp":"Primero proteger (PAS), luego RICE y derivación. Si hay deformidad o no puede apoyar nada, inmoviliza como está y llama al 131 (SAMU)."},{"t":"lectura","titulo":"Situación 2","texto":["Un compañero ayuda a subir al tren una maleta muy pesada de un adulto mayor. La levanta con la espalda doblada y siente un fuerte dolor en la zona lumbar."]},{"t":"mc","id":"s3-c2","p":"¿Cómo se clasifica esto y qué corresponde hacer?","ops":["Nada, fue un favor y no es parte del trabajo","Probable lumbago agudo por accidente del trabajo: detener la tarea, no forzar y derivar a su mutualidad u organismo administrador","Darle masajes fuertes hasta que pase","Que siga trabajando y lo vea en su casa"],"ok":1,"exp":"Ocurrió durante su turno, con ocasión del trabajo. Debe ir al organismo administrador de la Ley 16.744 y quedar registrado (DIAT)."},{"t":"mc","id":"s3-c3","p":"¿Qué técnica previene esta lesión la próxima vez?","ops":["Levantar rápido para que pese menos","Acercar la carga al cuerpo, doblar rodillas, espalda recta y pedir ayuda o un carro si supera lo razonable","Girar el tronco mientras se levanta","Usar solo los brazos"],"ok":1,"exp":"La carga cerca del cuerpo y la fuerza en las piernas protegen la espalda. La Ley 20.949 pide priorizar ayudas mecánicas."},{"t":"lectura","titulo":"Situación 3","texto":["Llevas 10 horas de pie en el control de acceso. De pronto se te acalambra el gemelo y el músculo se pone duro."]},{"t":"mc","id":"s3-c4","p":"¿Qué te pasa y qué haces?","ops":["Rotura fibrilar: inmovilizar y llamar ambulancia","Calambre: estirar suave el músculo, hidratarte y, si se repite, avisar para revisar las condiciones del puesto","Contractura: aplicar hielo 2 horas seguidas","Túnel carpiano: vendar la muñeca"],"ok":1,"exp":"El calambre es un espasmo involuntario, no permanente, ligado a sobreesfuerzo y pérdida de sales. Estar mucho tiempo de pie es un factor de riesgo, igual que las posturas forzadas."},{"t":"clasificar","id":"s3-c5","p":"En tu puesto de guardia, ¿qué factor de riesgo TMERT es cada situación?","cats":["Postura forzada o mantenida","Manejo de carga","Movimiento repetitivo"],"items":[["Estar de pie muchas horas en el mismo lugar",0],["Ayudar a subir equipaje pesado",1],["Revisar boletos con el mismo gesto de muñeca cientos de veces",2],["Mover vallas de control de multitudes",1]],"exp":"Así se ve el TMERT en tu trabajo. Identificar el factor es el primer paso para proponer una medida preventiva."}]}]}],"generado":"2026-11-13 11:35"};
